// away.go — a subring with one element inverted, inside a ring where
// that element is already a unit: the members r of the ring that some
// power of t brings into the subring, tⁿ · r ∈ S. When t has an inverse
// u in the ring these are the products a · uⁿ with a in S, the ring S[1/t]
// computed in place rather than as classes of fractions, and the inclusion
// of S into S[1/t] is a localization of S at the powers of t
// (RingAwayIsLocalization). An ideal of S[1/t] is generated by
// its meet with S, and a ring map from S to a field k inside S that fixes
// k and does not vanish at t extends to S[1/t], the ideal its kernel
// generates there being proper with residues in k. Inside a field, a
// spanning set and a basis of C over S stay one of C[1/t] over S[1/t];
// inverting a unit of S adds nothing, and inverting x and then y is
// inverting x · y. U[1/u] is the least subring holding U and the inverse of
// u, so it lies in every subfield holding U, inverting u again adds
// nothing, and a principal ideal domain stays one with u inverted. Two
// subrings, each inside the other once one element is inverted, become one
// ring after inverting one element of each.

package ring_away

import (
	"github.com/euc-ai/xugo/ext/on"
	. "github.com/euc-ai/xugo/library/authoring"
	"github.com/euc-ai/xugo/library/proofs/algebra/field/field"
	"github.com/euc-ai/xugo/library/proofs/algebra/group/comm_monoid"
	"github.com/euc-ai/xugo/library/proofs/algebra/module/linear_independence"
	"github.com/euc-ai/xugo/library/proofs/algebra/module/module"
	"github.com/euc-ai/xugo/library/proofs/algebra/module/module_record"
	"github.com/euc-ai/xugo/library/proofs/algebra/module/principal_ideal_domain"
	"github.com/euc-ai/xugo/library/proofs/algebra/module/submodule"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/comm_ring"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/fractional_ideal"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/integral_domain"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/quotient_ring"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/ring_homomorphism"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/ring_ideal"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/ring_localization"
	"github.com/euc-ai/xugo/library/proofs/nat_num/nat_order"
	"github.com/euc-ai/xugo/library/proofs/sets/set_basic"
	"github.com/euc-ai/xugo/library/proofs/sets/set_order"
	"github.com/euc-ai/xugo/library/registry"
	"github.com/euc-ai/xugo/prover/proof"
)

// RingAwayDef — `ring_away(R, S, t)`: the members of R that a power of t
// brings into S.
var RingAwayDef = ringAwayDefThm{family.Define(registry.DefEntry{
	Name:  "RingAwayDef",
	Key:   "prop_ac903ffe58eb336c",
	Const: "ring_away",
	Type:  "ring_ops(A) → set(A) → A → set(A)",
	Equations: []string{
		"∀R:ring_ops(A). ∀S:set(A). ∀t:A. " +
			"    ring_away(R, S, t) = " +
			"    {r:A | r ∈ R.carrier ∧ (∃n:num. R.mul(monoid_pow(R.mul, R.one, t, n), r) ∈ S)}",
	},
})}

// RingAwayMember — r lies in S[1/t] exactly when it lies in R and some
// power of t brings it into S: the definition's set-builder read at r.
var RingAwayMember = ringAwayMemberThm{family.Add(registry.ProofEntry{
	Name: "RingAwayMember",
	Key:  "prop_6932d00a03bbb228",
	Build: family.Theorem("∀R:ring_ops(A). ∀S:set(A). ∀t r:A. "+
		"    r ∈ ring_away(R, S, t) ⇔ "+
		"    r ∈ R.carrier ∧ (∃n:num. R.mul(monoid_pow(R.mul, R.one, t, n), r) ∈ S)",
		func(a *Argument, R *Expr[RingOps[A]], S *Expr[Set[A]], t, r *Expr[A]) {
			a.Show(
				"the set-builder read at r",
				Unfold(RingAwayDef),
				SetTacMembership())
		}),
})}

// RingAwaySubring — S[1/t] computed in R is a subring of R containing S,
// and contains the inverse of t when R has one: a member r of S lies in it
// at the exponent 0, the exponents of two members add under the sum and
// the product and stay under the negation, and a subset of R holding zero
// and one and closed under the operations is a subring.
var RingAwaySubring = ringAwaySubringThm{family.Add(registry.ProofEntry{
	Name: "RingAwaySubring",
	Key:  "prop_83ba7a5fc16492c6",
	Reading: "The sum of two members needs a common power: tᵐ · r ∈ S and tⁿ · r' ∈ S give " +
		"tᵐ⁺ⁿ · (r + r') ∈ S because S is closed under multiplication by t. The last clause asks " +
		"nothing of t: an inverse u of t in R, when there is one, lies in S[1/t] as t · u = one " +
		"∈ S. t ∈ S is load-bearing for the sums: there tᵐ ∈ S multiplies the other numerator.",
	Build: family.Theorem(Statement{
		Binders: "∀R:ring_ops(A). ∀S:set(A). ∀t:A.",
		Hypotheses: []string{
			"comm_ring_on(R)",
			"subring(R, S)",
			"t ∈ S",
		},
		Conclusion: "S ⊆ ring_away(R, S, t) ∧ " +
			"subring(R, ring_away(R, S, t)) ∧ " +
			"(∀u:A. u ∈ R.carrier ∧ R.mul(t, u) = R.one ⇒ u ∈ ring_away(R, S, t))",
	},
		func(a *Argument, R *Expr[RingOps[A]], S *Expr[Set[A]], t *Expr[A], hyps Fact) {
			parts := a.Conjuncts(
				hyps,
				"R is a ring on its carrier",
				"S is a subring of R",
				"t lies in S")
			ringR, subringS, tInS := parts[0], parts[1], parts[2]
			ringS := a.Have(
				"S is a ring under R's operations",
				"comm_ring_on(restrict_ring(R, S))",
				By(subringS, comm_ring.SubringRingOn.Read(ringR).At(S)))
			inR := a.Unfolded(a.Have(
				"S lies in R",
				"S ⊆ R.carrier",
				By(comm_ring.SubringSubset.Read(subringS))), set_basic.SubsetDef)
			tInR := a.Have(
				"t lies in R",
				"t ∈ R.carrier",
				By(inR, tInS))
			powers := a.Have(
				"every power of t lies in S",
				"∀n:num. monoid_pow(R.mul, R.one, t, n) ∈ S",
				By(comm_monoid.PowIn.Read(comm_ring.MulMonoidOn.Read(ringS)), tInS))
			membership := a.Have(
				"r lies in S[1/t] exactly when it lies in R and some power of t brings it into S",
				"∀r:A. r ∈ ring_away(R, S, t) ⇔ r ∈ R.carrier ∧ (∃n:num. monoid_pow(R.mul, R.one, t, n) * r ∈ S)",
				Unfold(RingAwayDef),
				SetTacMembership())
			sInAway := a.Have(
				"a member r of S lies in S[1/t] at the exponent 0",
				"S ⊆ ring_away(R, S, t)",
				Unfold(set_basic.SubsetDef),
				Derive(func(b *Argument) {
					r := b.FixAs[A]("r")
					rInS := b.Assume()
					atZero := b.Have(
						"t⁰ · r lies in S, a product of members of S",
						"monoid_pow(R.mul, R.one, t, 0) * r ∈ S",
						By(comm_ring.MulIn.Read(ringS), powers, rInS))
					b.Show(
						"so r lies in S[1/t]",
						By(Normalized, membership.At(r), inR, rInS, atZero))
				}))
			awayInR := a.Have(
				"S[1/t] lies in R",
				"ring_away(R, S, t) ⊆ R.carrier",
				Unfold(set_basic.SubsetDef),
				a.ForEach(func(r *Expr[A]) Action { return By(membership.At(r)) }))
			sumsAndProducts := a.Have(
				"S[1/t] is closed under the sum and the product, both at the sum of the two exponents",
				Statement{
					Binders: "∀x y:A.",
					Hypotheses: []string{
						"x ∈ ring_away(R, S, t)",
						"y ∈ ring_away(R, S, t)",
					},
					Conclusion: "x + y ∈ ring_away(R, S, t) ∧ x * y ∈ ring_away(R, S, t)",
				},
				Derive(func(b *Argument) {
					x, y := b.FixAs[A]("x"), b.FixAs[A]("y")
					members := b.Conjuncts(
						b.Assume(),
						"x lies in S[1/t]",
						"so does y")
					xInR := b.Have(
						"x lies in R",
						"x ∈ R.carrier",
						By(membership.At(x), members[0]))
					_, xm := b.Obtain(
						"some power tᵐ brings x into S",
						"∃m:num. monoid_pow(R.mul, R.one, t, m) * x ∈ S",
						By(membership.At(x), members[0]))
					yInR := b.Have(
						"y lies in R",
						"y ∈ R.carrier",
						By(membership.At(y), members[1]))
					_, yn := b.Obtain(
						"some power tⁿ brings y into S",
						"∃n:num. monoid_pow(R.mul, R.one, t, n) * y ∈ S",
						By(membership.At(y), members[1]))
					powerSum := b.Have(
						"tᵐ⁺ⁿ = tᵐ · tⁿ",
						"monoid_pow(R.mul, R.one, t, m + n) = "+
							"monoid_pow(R.mul, R.one, t, m) * monoid_pow(R.mul, R.one, t, n)",
						By(comm_monoid.PowAddOn.Read(comm_ring.MulMonoidOn.Read(ringR)), tInR))

					sum := b.TermAs[A]("x + y")
					regroupSum := b.Have(
						"tᵐ⁺ⁿ · (x + y) = tⁿ · (tᵐ · x) + tᵐ · (tⁿ · y)",
						"monoid_pow(R.mul, R.one, t, m + n) * (x + y) = "+
							"monoid_pow(R.mul, R.one, t, n) * (monoid_pow(R.mul, R.one, t, m) * x) + "+
							"monoid_pow(R.mul, R.one, t, m) * (monoid_pow(R.mul, R.one, t, n) * y)",
						ByArith(ringR, tInR, xInR, yInR, Scaled(sum, powerSum)))
					sumInS := b.Have(
						"which lies in S, built from tᵐ, tⁿ, tᵐ · x and tⁿ · y by the sum and the product",
						"monoid_pow(R.mul, R.one, t, m + n) * (x + y) ∈ S",
						regroupSum.Rw(),
						By(comm_ring.AddIn.Read(ringS), comm_ring.MulIn.Read(ringS), powers, xm, yn))
					sumInR := b.Have(
						"x + y lies in R",
						"x + y ∈ R.carrier",
						By(comm_ring.AddIn.Read(ringR), xInR, yInR))
					sumIn := b.Have(
						"so x + y lies in S[1/t]",
						"x + y ∈ ring_away(R, S, t)",
						By(membership.At(sum), sumInR, sumInS))

					product := b.TermAs[A]("x * y")
					regroupProduct := b.Have(
						"tᵐ⁺ⁿ · (x · y) = (tᵐ · x) · (tⁿ · y)",
						"monoid_pow(R.mul, R.one, t, m + n) * (x * y) = "+
							"(monoid_pow(R.mul, R.one, t, m) * x) * (monoid_pow(R.mul, R.one, t, n) * y)",
						ByArith(ringR, tInR, xInR, yInR, Scaled(product, powerSum)))
					productInS := b.Have(
						"which lies in S, a product of members of S",
						"monoid_pow(R.mul, R.one, t, m + n) * (x * y) ∈ S",
						regroupProduct.Rw(),
						By(comm_ring.MulIn.Read(ringS), xm, yn))
					productInR := b.Have(
						"x · y lies in R",
						"x * y ∈ R.carrier",
						By(comm_ring.MulIn.Read(ringR), xInR, yInR))
					productIn := b.Have(
						"so x · y lies in S[1/t]",
						"x * y ∈ ring_away(R, S, t)",
						By(membership.At(product), productInR, productInS))
					b.Show(
						"both lie in S[1/t]",
						By(sumIn, productIn))
				}))
			negations := a.Have(
				"S[1/t] is closed under the negation, at the same exponent",
				"∀x:A. x ∈ ring_away(R, S, t) ⇒ -x ∈ ring_away(R, S, t)",
				Derive(func(b *Argument) {
					x := b.FixAs[A]("x")
					member := b.Assume()
					xInR := b.Have(
						"x lies in R",
						"x ∈ R.carrier",
						By(membership.At(x), member))
					_, xm := b.Obtain(
						"some power tᵐ brings x into S",
						"∃m:num. monoid_pow(R.mul, R.one, t, m) * x ∈ S",
						By(membership.At(x), member))
					negate := b.Have(
						"tᵐ · -x = -(tᵐ · x)",
						"monoid_pow(R.mul, R.one, t, m) * -x = -(monoid_pow(R.mul, R.one, t, m) * x)",
						ByArith(ringR, tInR, xInR))
					inS := b.Have(
						"which lies in S, the negation of a member of S",
						"monoid_pow(R.mul, R.one, t, m) * -x ∈ S",
						negate.Rw(),
						By(comm_ring.NegIn.Read(ringS), xm))
					b.Show(
						"so -x lies in S[1/t]",
						By(membership.At(b.TermAs[A]("-x")), comm_ring.NegIn.Read(ringR), xInR, inS))
				}))
			fromS := a.Unfolded(sInAway, set_basic.SubsetDef)
			subringAway := a.Have(
				"so S[1/t] is a subring of R, a subset of R holding zero and one and closed under its operations",
				"subring(R, ring_away(R, S, t))",
				Simp(Fwd(comm_ring.SubringDef)),
				By(
					awayInR,
					fromS,
					comm_ring.ZeroIn.Read(ringS),
					comm_ring.OneIn.Read(ringS),
					sumsAndProducts,
					negations))
			inverse := a.Have(
				"an inverse u of t lies in S[1/t] at the exponent 1, as t · u = one lies in S",
				"∀u:A. u ∈ R.carrier ∧ t * u = R.one ⇒ u ∈ ring_away(R, S, t)",
				Derive(func(b *Argument) {
					u := b.FixAs[A]("u")
					given := b.Conjuncts(
						b.Assume(),
						"u lies in R",
						"t · u = one")
					atOne := b.Have(
						"t¹ · u = t · u = one",
						"monoid_pow(R.mul, R.one, t, 1) * u = R.one",
						ByArith(ringR, tInR, given[0], given[1]))
					inS := b.Have(
						"which lies in S",
						"monoid_pow(R.mul, R.one, t, 1) * u ∈ S",
						atOne.Rw(),
						By(comm_ring.OneIn.Read(ringS)))
					b.Show(
						"so u lies in S[1/t]",
						By(Normalized, membership.At(u), given[0], inS))
				}))
			a.Show(
				"S ⊆ S[1/t], S[1/t] is a subring of R, and it holds the inverse of t",
				By(sInAway, subringAway, inverse))
		}),
})}

// RingAwayIdeal — denominator saturation of an ideal is an ideal of the
// away ring and contains the ideal: adding denominator exponents clears
// sums and scalar products back into the original ideal.
var RingAwayIdeal = ringAwayIdealThm{family.Add(registry.ProofEntry{
	Name: "RingAwayIdeal",
	Key:  "prop_96630c2ed117f355",
	Build: family.Theorem(Statement{
		Binders:    "∀L:field_on(A). ∀S I:set(A). ∀u:A.",
		Hypotheses: []string{"subring(field_ring(L), S)", "u ∈ S", "ring_ideal(«R», I)"},
		Conclusion: "ring_ideal(«Localized», «Saturated») ∧ I ⊆ «Saturated»",
		Abbrev: Abbrev{
			{Name: "R", Text: "restrict_ring(field_ring(L), S)"},
			{Name: "Away", Text: "ring_away(field_ring(L), S, u)"},
			{Name: "Localized", Text: "restrict_ring(field_ring(L), «Away»)"},
			{Name: "Pow", Text: "λk:num. monoid_pow(L.mul, L.one, u, k)"},
			{Name: "Saturated", Text: "ring_away(field_ring(L), I, u)"},
		},
	}, func(a *Argument, L field.FieldFact[on.L], S, I *Expr[Set[A]], u *Expr[A], h Fact) {
		parts := a.Conjuncts(
			h,
			"S is a subring",
			"u belongs to S",
			"I is an ideal of S")
		subringS, uIn, idealI := parts[0], parts[1], parts[2]
		ops := a.TermAs[RingOps[A]]("«R»")
		fieldRing := a.TermAs[RingOps[A]]("field_ring(L)")
		ring := field.RingOn.Read(L)
		mul := comm_ring.MulMonoidOn.Read(ring)
		carriers := a.Have(
			"the ideal and S lie in the ambient field",
			"I ⊆ S ∧ S ⊆ L.carrier ∧ u ∈ L.carrier",
			BySets(
				idealI,
				uIn,
				subringS,
				ring_ideal.IdealSubset.At(ops, I),
				comm_ring.SubringSubset.At(fieldRing, S)))
		contains := a.Have(
			"every member of I is saturated at exponent zero",
			"I ⊆ «Saturated»",
			Simp(Fwd(set_basic.SubsetDef)),
			Derive(func(b *Argument) {
				b.FixAs[A]("x")
				xIn := b.Assume()
				xField := b.Have(
					"the ideal member belongs to the field",
					"x ∈ L.carrier",
					BySets(xIn, carriers))
				b.Show(
					"use the zeroth denominator power",
					Simp(Fwd(RingAwayMember)),
					SplitConj(
						Case(
							"the numerator belongs to the field",
							By(xField)),
						Case(
							"the denominator exponent is zero",
							Derive(func(c *Argument) {
								c.Take(c.TermAs[Nat]("0"))
								c.Show(
									"the zeroth power acts as one",
									Simp(Fwd(comm_monoid.MonoidPowDef), Fwd(comm_monoid.LeftIdentityOn.Read(mul))),
									By(xIn))
							}))))
			}))
		saturatedIdeal := a.Have(
			"the saturated set is an ideal of the away ring",
			"ring_ideal(«Localized», «Saturated»)",
			Simp(Fwd(ring_ideal.RingIdealDef)),
			SplitConjAll(
				Case(
					"an I-denominator also clears into S",
					BySets(carriers, RingAwayDef.At(fieldRing, I, u), RingAwayDef.At(fieldRing, S, u))),
				Case(
					"zero is already in the original ideal",
					BySets(idealI, contains, ring_ideal.IdealZero.At(ops, I))),
				Case(
					"add two saturated elements with a common denominator",
					Derive(func(b *Argument) {
						b.FixAs[A]("x")
						b.FixAs[A]("y")
						members := b.Assume()
						k, l, denominators := b.Obtain2As[Nat, Nat](
							"choose one denominator exponent for each summand",
							"∃k l:num. x ∈ L.carrier ∧ y ∈ L.carrier ∧ «Pow»(k) * x ∈ I ∧ «Pow»(l) * y ∈ I",
							BySets(members, RingAwayDef.At(fieldRing, I, u)))
						ringS := b.Have(
							"S is a commutative ring",
							"comm_ring_on(«R»)",
							By(subringS, comm_ring.SubringRingOn.Read(ring).At(S)))
						powers := b.Have(
							"the additional powers used to clear denominators lie in S",
							"«Pow»(k) ∈ S ∧ «Pow»(l) ∈ S",
							By(
								uIn,
								comm_monoid.PowIn.Read(comm_ring.MulMonoidOn.Read(ringS)).AsFact().At(u, k),
								comm_monoid.PowIn.Read(comm_ring.MulMonoidOn.Read(ringS)).AsFact().At(u, l)))
						common := b.Have(
							"the sum of exponents clears both summands",
							"«Pow»(k + l) * (x + y) = «Pow»(l) * («Pow»(k) * x) + «Pow»(k) * («Pow»(l) * y)",
							Simp(Fwd(comm_monoid.PowAddOn.Read(mul))),
							ByArith(L, carriers, denominators))
						b.Show(
							"the cleared sum belongs to I by absorption and addition",
							Simp(Fwd(RingAwayMember)),
							SplitConj(
								Case(
									"the sum belongs to the field",
									By(denominators, comm_ring.AddIn.Read(ring))),
								Case(
									"use the sum of denominator exponents",
									Derive(func(c *Argument) {
										c.Take(c.TermAs[Nat]("k + l"))
										c.Show(
											"the two cleared summands and their sum remain in I",
											By(
												common,
												idealI,
												powers,
												denominators,
												ring_ideal.IdealMul.At(ops, I, c.TermAs[A]("«Pow»(l)"), c.TermAs[A]("«Pow»(k) * x")),
												ring_ideal.IdealMul.At(ops, I, c.TermAs[A]("«Pow»(k)"), c.TermAs[A]("«Pow»(l) * y")),
												ring_ideal.IdealAdd.At(
													ops, I, c.TermAs[A]("«Pow»(l) * («Pow»(k) * x)"), c.TermAs[A]("«Pow»(k) * («Pow»(l) * y)"))))
									}))))
					})),
				Case(
					"multiply a saturated element by a member of the away ring",
					Derive(func(b *Argument) {
						b.FixAs[A]("r")
						b.FixAs[A]("x")
						members := b.Assume()
						_, _, denominators := b.Obtain2As[Nat, Nat](
							"clear the scalar into S and the ideal member into I",
							"∃k l:num. r ∈ L.carrier ∧ x ∈ L.carrier ∧ «Pow»(k) * r ∈ S ∧ «Pow»(l) * x ∈ I",
							BySets(members, RingAwayDef.At(fieldRing, S, u), RingAwayDef.At(fieldRing, I, u)))
						common := b.Have(
							"the cleared product is a scalar in S times a member of I",
							"«Pow»(k + l) * (r * x) = («Pow»(k) * r) * («Pow»(l) * x)",
							Simp(Fwd(comm_monoid.PowAddOn.Read(mul))),
							ByArith(L, carriers, denominators))
						b.Show(
							"the product is saturated",
							Simp(Fwd(RingAwayMember)),
							SplitConj(
								Case(
									"the product belongs to the field",
									By(denominators, comm_ring.MulIn.Read(ring))),
								Case(
									"add the two denominator exponents",
									Derive(func(c *Argument) {
										c.Take(c.TermAs[Nat]("k + l"))
										c.Show(
											"ideal absorption holds after clearing denominators",
											By(
												idealI,
												denominators,
												common,
												ring_ideal.IdealMul.At(ops, I, c.TermAs[A]("«Pow»(k) * r"), c.TermAs[A]("«Pow»(l) * x"))))
									}))))
					}))))
		a.Show(
			"saturation is an ideal containing I",
			By(saturatedIdeal, contains))
	}),
})}

// RingAwayProducts — for S a subset of R and t a member of R with an
// inverse u in R, S[1/t] is the set of products a · uⁿ with a in S: the
// powers cancel, tⁿ · uⁿ = one, so tⁿ brings a product a · uⁿ back to
// a ∈ S, and a member r that tⁿ brings into S is the product (tⁿ · r) · uⁿ.
var RingAwayProducts = ringAwayProductsThm{family.Add(registry.ProofEntry{
	Name: "RingAwayProducts",
	Key:  "prop_c08629cdd4de2bb3",
	Reading: "S is any subset of R and t any member of R with an inverse u in R: " +
		"neither a ring structure on S nor t ∈ S is asked, so the description holds for " +
		"numerators that do not form a ring, and S = ∅ gives the empty set on both sides.",
	Build: family.Theorem(Statement{
		Binders: "∀R:ring_ops(A). ∀S:set(A). ∀t u:A.",
		Hypotheses: []string{
			"comm_ring_on(R)",
			"S ⊆ R.carrier",
			"t ∈ R.carrier",
			"u ∈ R.carrier",
			"R.mul(t, u) = R.one",
		},
		Conclusion: "ring_away(R, S, t) = {R.mul(a, monoid_pow(R.mul, R.one, u, n)) | a:A, n:num | a ∈ S}",
	},
		func(
			a *Argument,
			R *Expr[RingOps[A]],
			ring comm_ring.CommRingFact[on.R],
			S *Expr[Set[A]],
			t, u *Expr[A],
			given Fact,
		) {
			hypotheses := a.Conjuncts(
				given,
				"S lies in R",
				"t lies in R",
				"u lies in R",
				"t · u = one")
			sInR, tInR, uInR, inverse := hypotheses[0], hypotheses[1], hypotheses[2], hypotheses[3]
			tm := a.MemberOf[on.R](t, tInR)
			um := a.MemberOf[on.R](u, uInR)
			monoid := comm_ring.MulMonoidOn.Read(ring)
			inversePowers := a.Have(
				"tⁿ · uⁿ = one for every n, t · u being one",
				"∀n:num. monoid_pow(R.mul, R.one, t, n) * monoid_pow(R.mul, R.one, u, n) = R.one",
				By(comm_monoid.PowInverseOn.Read(monoid), tm, um, inverse))

			products := a.Have(
				"a product a · uⁿ with a in S lies in S[1/t], tⁿ bringing it back to a",
				"∀a:A. ∀n:num. a ∈ S ⇒ a * monoid_pow(R.mul, R.one, u, n) ∈ ring_away(R, S, t)",
				Derive(func(b *Argument) {
					elem, n := b.FixAs[A]("a"), b.FixAs[Nat]("n")
					inS := b.Assume()
					em := b.MemberOf[on.R](elem, b.Have(
						"a lies in R",
						"a ∈ R.carrier",
						BySets(inS, sInR)))
					cancelled := b.Have(
						"tⁿ · (a · uⁿ) = a, the powers cancelling",
						"monoid_pow(R.mul, R.one, t, n) * (a * monoid_pow(R.mul, R.one, u, n)) = a",
						ByArith(ring, tm, um, em, Scaled(elem, inversePowers.At(n))))
					product := comm_ring.MulIn.Read(ring).At(em, comm_monoid.PowIn.Read(monoid).At(um, n))
					b.Show(
						"so a · uⁿ lies in S[1/t]: it lies in R, and tⁿ brings it to a ∈ S",
						By(RingAwayMember.At(R, S, t, product), product, cancelled, inS))
				}))
			recovered := a.Have(
				"a member r of S[1/t] is the product (tⁿ · r) · uⁿ, for the n bringing it into S",
				"∀r:A. r ∈ ring_away(R, S, t) ⇒ ∃a:A. ∃n:num. a ∈ S ∧ r = a * monoid_pow(R.mul, R.one, u, n)",
				Derive(func(b *Argument) {
					r := b.FixAs[A]("r")
					member := b.Assume()
					opened := b.Conjuncts(
						b.Simplified(member, Fwd(RingAwayMember)),
						"r lies in R",
						"a power of t brings r into S")
					n, cleared := b.UnpackAs[Nat](opened[1], "n")
					rm := b.MemberOf[on.R](r, opened[0])
					restored := b.Have(
						"r = (tⁿ · r) · uⁿ, the powers cancelling",
						"r = (monoid_pow(R.mul, R.one, t, n) * r) * monoid_pow(R.mul, R.one, u, n)",
						ByArith(ring, tm, um, rm, Scaled(r, inversePowers.At(n))))
					b.Take(b.TermAs[A]("monoid_pow(R.mul, R.one, t, n) * r"))
					b.Take(n)
					b.Show(
						"so r is the product at tⁿ · r ∈ S and n",
						By(cleared, restored))
				}))
			a.Show(
				"so S[1/t] is exactly the set of those products",
				BySets(recovered, products))
		}),
})}

// RingAwayInSubring — C with t inverted, computed in a subring S of R
// that holds C and an inverse u of t, is C with t inverted computed in R:
// computed in either ring it is the set of products a · uⁿ with a in C,
// and S multiplies as R does.
var RingAwayInSubring = ringAwayInSubringThm{family.Add(registry.ProofEntry{
	Name: "RingAwayInSubring",
	Key:  "prop_1074a3ad0d4d7be9",
	Build: family.Theorem(Statement{
		Binders: "∀R:ring_ops(A). ∀S C:set(A). ∀t u:A.",
		Hypotheses: []string{
			"comm_ring_on(R)",
			"subring(R, S)",
			"t ∈ S",
			"C ⊆ S",
			"u ∈ S",
			"R.mul(t, u) = R.one",
		},
		Conclusion: "ring_away(restrict_ring(R, S), C, t) = ring_away(R, C, t)",
		Abbrev: Abbrev{
			{Name: "inSubring", Text: "ring_away(restrict_ring(R, S), C, t)"},
		},
	},
		func(a *Argument, R *Expr[RingOps[A]], S, C *Expr[Set[A]], t, u *Expr[A], h Fact) {
			parts := a.Conjuncts(
				h,
				"R is a ring on its carrier",
				"S is a subring of R",
				"t lies in S",
				"C lies in S",
				"u lies in S",
				"t · u = one")
			ringR, subringS, tInS, cInS, uInS, inverse :=
				parts[0], parts[1], parts[2], parts[3], parts[4], parts[5]
			sInR := a.Have(
				"S lies in R",
				"S ⊆ R.carrier",
				By(comm_ring.SubringSubset.Read(subringS)))
			ringS := a.Have(
				"S is a ring under R's operations",
				"comm_ring_on(restrict_ring(R, S))",
				By(subringS, comm_ring.SubringRingOn.Read(ringR).At(S)))
			cInR := a.Have(
				"C lies in R",
				"C ⊆ R.carrier",
				BySets(cInS, sInR))
			tm := proof.MemberOf(t, a.Have(
				"t lies in R",
				"t ∈ R.carrier",
				BySets(tInS, sInR)))
			um := proof.MemberOf(u, a.Have(
				"u lies in R",
				"u ∈ R.carrier",
				BySets(uInS, sInR)))
			a.Show(
				"computed in S or in R, C[1/t] is the set of products a · uⁿ with a in C",
				CalcEq(
					Leg(
						a.TermAs[Set[A]]("{a * monoid_pow(R.mul, R.one, u, n) | a:A, n:num | a ∈ C}"),
						"in S, whose multiplication is R's",
						By(
							cInS,
							inverse,
							RingAwayProducts.Read(ringS).At(C, proof.MemberOf(t, tInS), proof.MemberOf(u, uInS)))),
					FinalLeg(
						"and in R",
						By(cInR, inverse, RingAwayProducts.Read(ringR).At(C, tm, um))),
				))
		}),
})}

// RingAwayIsLocalization — when t ∈ S has the inverse u in R, the
// inclusion of S into S[1/t] is the localization of S at the powers of t:
// the powers of t are a multiplicative subset of the ring S; S and S[1/t]
// are rings under R's operations, so the inclusion is a ring map; u lies
// in S[1/t], so t is a unit there and so is each power tⁿ; a member r of
// S[1/t] is the fraction (tⁿ · r)/tⁿ for an n that brings it into S; and a
// member of S sent to zero is zero, which the denominator one kills.
var RingAwayIsLocalization = ringAwayIsLocalizationThm{family.Add(registry.ProofEntry{
	Name: "RingAwayIsLocalization",
	Key:  "prop_9b0f3f4e0fca1960",
	Reading: "t ∈ S puts every power of t in S, so the powers are a multiplicative " +
		"subset of S. u ∈ R.carrier and t * u = R.one put u in S[1/t], where it " +
		"inverts t; u need lie only in R, and S[1/t] is S itself when u lies in S.",
	Build: family.Theorem(Statement{
		Binders: "∀R:ring_ops(A). ∀S:set(A). ∀t u:A.",
		Hypotheses: []string{
			"comm_ring_on(R)",
			"subring(R, S)",
			"t ∈ S",
			"u ∈ R.carrier",
			"t * u = R.one",
		},
		Conclusion: "is_localization_on(restrict_ring(R, S), " +
			"    monoid_powers(R.mul, R.one, t), " +
			"    restrict_ring(R, ring_away(R, S, t)), " +
			"    λx:A. x)",
	},
		func(
			a *Argument,
			R *Expr[RingOps[A]],
			ring comm_ring.CommRingFact[on.R],
			S *Expr[Set[A]],
			t, u *Expr[A],
			given Fact,
		) {
			hypotheses := a.Conjuncts(
				given,
				"S is a subring of R",
				"t lies in S",
				"u lies in R",
				"t · u = one")
			subringS, tInS, uInR, inverse := hypotheses[0], hypotheses[1], hypotheses[2], hypotheses[3]
			tInR := a.Have(
				"t lies in R, as S does",
				"t ∈ R.carrier",
				BySets(tInS, comm_ring.SubringSubset.Read(subringS)))
			tm := a.MemberOf[on.R](t, tInR)
			away := a.Conjuncts(
				GroupPremises(ring, subringS, tInS, RingAwaySubring.At(R, S, t)),
				"S lies in S[1/t]",
				"S[1/t] is a subring of R",
				"S[1/t] holds every inverse of t")
			sInAway, subringAway, inverses := away[0], away[1], away[2]
			uInAway := a.Have(
				"u lies in S[1/t]",
				"u ∈ ring_away(R, S, t)",
				By(uInR, inverse, inverses.At(u)))
			ringS := a.Have(
				"S is a ring under R's operations",
				"comm_ring_on(restrict_ring(R, S))",
				By(subringS, comm_ring.SubringRingOn.Read(ring).At(S)))
			ringAway := a.Have(
				"and so is S[1/t]",
				"comm_ring_on(restrict_ring(R, ring_away(R, S, t)))",
				By(subringAway, comm_ring.SubringRingOn.Read(ring).At(a.TermAs[Set[A]]("ring_away(R, S, t)"))))
			tUnit := a.Have(
				"t is a unit of S[1/t], u inverting it there",
				"ring_unit(restrict_ring(R, ring_away(R, S, t)), t)",
				Simp(Fwd(ring_ideal.RingUnitDef)),
				SplitConj(
					Case(
						"t lies in S, so in S[1/t]",
						BySets(tInS, sInAway)),
					Case(
						"u lies in S[1/t], and t · u = one",
						Witness(u),
						By(uInAway, inverse)),
				))
			multiplicative := a.Have(
				"the powers of t form a multiplicative subset of the ring S, which holds t",
				"multiplicative_set(S, monoid_powers(R.mul, R.one, t))",
				By(tInS, ring_localization.PowersMultiplicative.Read(ringS)))
			a.Show(
				"S → S[1/t] is the localization of S at the powers of t",
				Simp(Fwd(ring_localization.IsLocalizationOnDef)),
				SplitConjAll(
					Case(
						"the powers of t form a multiplicative subset of S",
						By(multiplicative)),
					Case(
						"the inclusion is a ring map: S and S[1/t] are rings under R's operations, and S lies in S[1/t]",
						Simp(Fwd(ring_homomorphism.RingHomomorphism)),
						BySets(ringS, ringAway, sInAway)),
					Case(
						"each power tⁿ is a unit of S[1/t], a power of the unit t",
						Derive(func(b *Argument) {
							b.FixAs[A]("s")
							power := b.Assume()
							n, exponent := b.ObtainAs[Nat](
								"s is a power tⁿ",
								"∃n:num. s = monoid_pow(R.mul, R.one, t, n)",
								BySets(power, comm_monoid.MonoidPowersDef))
							b.Do(exponent.Rw())
							b.Show(
								"a power of a unit is a unit",
								By(tUnit, ring_ideal.RingUnitPow.Read(ringAway).At(t, n)))
						})),
					Case(
						"a member r of S[1/t] is the fraction (tⁿ · r)/tⁿ, for a power tⁿ that brings it into S",
						Derive(func(b *Argument) {
							b.FixAs[A]("r")
							member := b.Assume()
							opened := b.Conjuncts(
								b.Simplified(member, Fwd(RingAwayMember)),
								"r lies in R",
								"a power of t brings r into S")
							_, cleared := b.UnpackAs[Nat](opened[1], "n")
							b.Take(b.TermAs[A]("monoid_pow(R.mul, R.one, t, n) * r"))
							b.Take(b.TermAs[A]("monoid_pow(R.mul, R.one, t, n)"))
							b.Show(
								"tⁿ · r lies in S, tⁿ is a power of t, and r · tⁿ = tⁿ · r",
								SplitConjAll(
									Case(
										"tⁿ · r lies in S",
										By(cleared)),
									Case(
										"tⁿ is a power of t",
										BySets(comm_monoid.MonoidPowersDef)),
									Case(
										"r · tⁿ = tⁿ · r, R being commutative",
										ByArith(ring, opened[0], tm)),
								))
						})),
					Case(
						"a member x of S sent to zero is zero, which the denominator one kills",
						Derive(func(b *Argument) {
							b.FixAs[A]("x")
							killed := b.Conjuncts(
								b.Assume(),
								"x lies in S",
								"x is zero")
							b.Take(b.TermAs[A]("R.one"))
							b.Do(killed[1].Rw())
							b.Show(
								"one is a power of t, and one · zero = zero",
								SplitConj(
									Case(
										"one is a power of t, the powers being a multiplicative set",
										By(multiplicative, ring_localization.MultiplicativeSetDef)),
									Case(
										"one · zero = zero",
										ByArith(ring)),
								))
						})),
				))
		}),
})}

// RingAwaySpanOfContraction — an ideal J of R = S[1/d], d having the
// inverse e in R, is generated by its contraction S ∩ J. The span lies in J
// as J is an ideal holding S ∩ J; a member r of J has dⁿ · r in S for some
// n, so in S ∩ J, and eⁿ · (dⁿ · r) = r brings it back into the span. It is
// the ideal form of the statement for modules that the span over R of a
// submodule over S holds exactly the vectors a power of d brings into it.
var RingAwaySpanOfContraction = ringAwaySpanOfContractionThm{family.Add(registry.ProofEntry{
	Name: "RingAwaySpanOfContraction",
	Key:  "prop_ddb71ef657acaa32",
	Build: family.Theorem(Statement{
		Binders: "∀R:ring_ops(A). ∀S:set(A). ∀d e:A. ∀J:set(A).",
		Hypotheses: []string{
			"comm_ring_on(R)",
			"subring(R, S)",
			"d ∈ S",
			"e ∈ R.carrier",
			"d * e = R.one",
			"R.carrier = ring_away(R, S, d)",
			"ring_ideal(R, J)",
		},
		Conclusion: "ideal_span(R, S ∩ J) = J",
	},
		func(
			a *Argument,
			R *Expr[RingOps[A]],
			ring comm_ring.CommRingFact[on.R],
			S *Expr[Set[A]],
			d, e *Expr[A],
			J *Expr[Set[A]],
			given Fact,
		) {
			hypotheses := a.Conjuncts(
				given,
				"S is a subring",
				"d lies in S",
				"e lies in R",
				"d and e are inverse",
				"inverting d gives R",
				"J is an ideal of R")
			subringS, dInS, eInR, product, away, idealJ :=
				hypotheses[0], hypotheses[1], hypotheses[2], hypotheses[3], hypotheses[4], hypotheses[5]
			contractedSubset := a.Have(
				"the contraction lies in J",
				"S ∩ J ⊆ J",
				BySets())
			spanSubset := a.Have(
				"the generated ideal lies in the ambient ideal by leastness",
				"ideal_span(R, S ∩ J) ⊆ J",
				By(idealJ, contractedSubset, ring_ideal.SpanLeast.At(R, a.TermAs[Set[A]]("S ∩ J"), J)))
			contractedInR := a.Have(
				"the contraction lies in R",
				"S ∩ J ⊆ R.carrier",
				BySets(ring_ideal.IdealSubset.Read(idealJ)))
			contractionSpanIdeal := a.Have(
				"its span is an ideal of R",
				"ring_ideal(R, ideal_span(R, S ∩ J))",
				By(contractedInR, ring_ideal.SpanIdeal.Read(ring).AsFact().At(a.TermAs[Set[A]]("S ∩ J"))))
			denominatorInR := a.Have(
				"d lies in R",
				"d ∈ R.carrier",
				BySets(comm_ring.SubringSubset.Read(subringS), dInS))
			recoveredMembers := a.Have(
				"each ambient ideal element returns to the span after clearing denominators",
				"∀r:A. r ∈ J ⇒ r ∈ ideal_span(R, S ∩ J)",
				Derive(func(b *Argument) {
					r := b.FixAs[A]()
					premises := b.Assume()
					idealMemberInR := b.Have(
						"an element of the ambient ideal lies in R",
						"r ∈ R.carrier",
						BySets(ring_ideal.IdealSubset.Read(idealJ), premises))
					idealMemberAway := b.Have(
						"the element belongs to the localization carrier",
						"r ∈ ring_away(R, S, d)",
						By(Normalized, idealMemberInR, away))
					n, denominatorPower := b.ObtainAs[Nat](
						"choose a power of d that brings r into S",
						"∃n:num. monoid_pow(R.mul, R.one, d, n) * r ∈ S",
						By(idealMemberAway, RingAwayMember.At(R, S, d, r)))
					powersInR := b.Have(
						"the denominator and inverse powers lie in R",
						"monoid_pow(R.mul, R.one, d, n) ∈ R.carrier ∧ monoid_pow(R.mul, R.one, e, n) ∈ R.carrier",
						By(
							denominatorInR,
							eInR,
							comm_monoid.PowIn.Read(comm_ring.MulMonoidOn.Read(ring)).AsFact().At(d, n),
							comm_monoid.PowIn.Read(comm_ring.MulMonoidOn.Read(ring)).AsFact().At(e, n)))
					inversePowers := b.Have(
						"those powers multiply to one",
						"monoid_pow(R.mul, R.one, d, n) * monoid_pow(R.mul, R.one, e, n) = R.one",
						By(
							denominatorInR,
							eInR,
							product,
							comm_monoid.PowInverseOn.Read(comm_ring.MulMonoidOn.Read(ring)).AsFact().At(d, e, n)))
					clearedInIdeal := b.Have(
						"the cleared element remains in the ambient ideal",
						"monoid_pow(R.mul, R.one, d, n) * r ∈ J",
						By(
							powersInR,
							premises,
							ring_ideal.IdealMul.Read(idealJ).AsFact().At(b.TermAs[A]("monoid_pow(R.mul, R.one, d, n)"), r)))
					clearedInSpan := b.Have(
						"the cleared element lies in the span of the contraction",
						"monoid_pow(R.mul, R.one, d, n) * r ∈ ideal_span(R, S ∩ J)",
						BySets(denominatorPower, clearedInIdeal, ring_ideal.SpanContains.At(R, b.TermAs[Set[A]]("S ∩ J"))))
					recoveredInSpan := b.Have(
						"multiplying back by the inverse power stays in that span",
						"monoid_pow(R.mul, R.one, e, n) * (monoid_pow(R.mul, R.one, d, n) * r) ∈ ideal_span(R, S ∩ J)",
						By(
							powersInR,
							clearedInSpan,
							ring_ideal.IdealMul.Read(contractionSpanIdeal).AsFact().At(
								b.TermAs[A]("monoid_pow(R.mul, R.one, e, n)"), b.TermAs[A]("monoid_pow(R.mul, R.one, d, n) * r"))))
					recoverIdentity := b.Have(
						"the inverse power recovers the original element",
						"monoid_pow(R.mul, R.one, e, n) * (monoid_pow(R.mul, R.one, d, n) * r) = r",
						ByArith(ring, powersInR, idealMemberInR, Scaled(r, inversePowers)))
					b.Show(
						"the inverse power brings the original element back into the span",
						By(Normalized, recoveredInSpan, recoverIdentity))
				}))
			idealSubsetSpan := a.Have(
				"every element of the ambient ideal lies in the span",
				"J ⊆ ideal_span(R, S ∩ J)",
				BySets(recoveredMembers))
			a.Show(
				"the two containments identify the ambient ideal",
				By(spanSubset, idealSubsetSpan, set_order.SubsetAntisym))
		}),
})}

// InclusionIsLocalizationAway — when R is S with d inverted, d having the
// inverse e in R, the inclusion of S into R is the localization of S at
// the powers of d: the inclusion of S into S[1/d] is that localization
// (RingAwayIsLocalization), and S[1/d] read as a ring inside R is R
// itself, the two having one carrier.
var InclusionIsLocalizationAway = inclusionIsLocalizationAwayThm{family.Add(registry.ProofEntry{
	Name: "InclusionIsLocalizationAway",
	Key:  "prop_56fe1ce8e962f8e7",
	Build: family.Theorem(Statement{
		Binders: "∀R:ring_ops(A). ∀S:set(A). ∀d e:A.",
		Hypotheses: []string{
			"comm_ring_on(R)",
			"subring(R, S)",
			"d ∈ S",
			"e ∈ R.carrier",
			"d * e = R.one",
			"R.carrier = ring_away(R, S, d)",
		},
		Conclusion: "is_localization_on(restrict_ring(R, S), monoid_powers(R.mul, R.one, d), R, λx:A. x)",
	},
		func(
			a *Argument,
			R *Expr[RingOps[A]],
			ring comm_ring.CommRingFact[on.R],
			S *Expr[Set[A]],
			d, e *Expr[A],
			given Fact,
		) {
			hypotheses := a.Conjuncts(
				given,
				"S is a subring of R",
				"d lies in S",
				"e lies in R",
				"d · e = one",
				"R is S with d inverted")
			subringS, dInS, eInR, product, away :=
				hypotheses[0], hypotheses[1], hypotheses[2], hypotheses[3], hypotheses[4]
			awayLocalization := a.Have(
				"the inclusion of S into S[1/d] is its localization at the powers of d",
				"is_localization_on(restrict_ring(R, S), "+
					"    monoid_powers(R.mul, R.one, d), "+
					"    restrict_ring(R, ring_away(R, S, d)), "+
					"    λx:A. x)",
				By(ring, subringS, dInS, eInR, product, RingAwayIsLocalization.At(R, S, d, e)))
			a.Show(
				"and S[1/d], read inside R, is R",
				By(awayLocalization, away, module_record.RestrictRingCarrier))
		}),
})}

// HomomorphismExtendsAway — a ring map φ : S → k fixing the field k that
// does not vanish at d extends to a ring map ψ : S[1/d] → k, here R; ψ
// fixes k, its kernel is the ideal ker φ generates in R, and it meets S in
// ker φ. d is a unit of R, so S → R is the localization of S at the powers
// of d (InclusionIsLocalizationAway); φ sends every power of d to a power
// of φ(d), a unit of k, so the universal property gives ψ. Agreement makes
// ψ fix k and S ∩ ker ψ = ker φ, and the ideal ker ψ of R = S[1/d] is
// generated by that contraction.
var HomomorphismExtendsAway = homomorphismExtendsAwayThm{family.Add(registry.ProofEntry{
	Name: "HomomorphismExtendsAway",
	Key:  "prop_2cf5758e14b1be1e",
	Reading: "φ(d) ≠ zero is load-bearing: were φ(d) zero, d would lie in ker φ, and d being " +
		"a unit of R, ker φ would generate all of R, the kernel of no ring map to k fixing k.",
	Build: family.Theorem(Statement{
		Binders: "∀R:ring_ops(A). ∀k:set(A). ∀inv:(A → A). ∀S:set(A). ∀d e:A. ∀φ:(A → A).",
		Hypotheses: []string{
			"comm_ring_on(R)",
			"ring_subfield(R, inv, k)",
			"subring(R, S)",
			"k ⊆ S",
			"d ∈ S",
			"e ∈ R.carrier",
			"d * e = R.one",
			"R.carrier = ring_away(R, S, d)",
			"ring_homomorphism(restrict_ring(R, S), restrict_ring(R, k), φ)",
			"∀c:A. c ∈ k ⇒ φ(c) = c",
			"φ(d) ≠ R.zero",
		},
		Conclusion: "∃ψ:(A → A). " +
			"    ring_homomorphism(R, restrict_ring(R, k), ψ) ∧ " +
			"    (∀x:A. x ∈ S ⇒ ψ(x) = φ(x)) ∧ " +
			"    (∀c:A. c ∈ k ⇒ ψ(c) = c) ∧ " +
			"    ideal_span(R, ring_kernel(R.zero, S, φ)) = ring_kernel(R.zero, R.carrier, ψ) ∧ " +
			"    S ∩ ring_kernel(R.zero, R.carrier, ψ) = ring_kernel(R.zero, S, φ)",
	},
		func(
			a *Argument,
			R *Expr[RingOps[A]],
			ring comm_ring.CommRingFact[on.R],
			k *Expr[Set[A]],
			inv *Arrow[A, A],
			subfieldK Fact,
			S *Expr[Set[A]],
			d, e *Expr[A],
			φ *Arrow[A, A],
			given Fact,
		) {
			hypotheses := a.Conjuncts(
				given,
				"S is a subring of R",
				"k lies in S",
				"d lies in S",
				"e lies in R",
				"d · e = one",
				"R is S with d inverted",
				"φ is a ring map from S to k",
				"φ fixes k",
				"φ does not vanish at d")
			subringS, kInS, dInS, eInR, product, away, ringMap, fixesK, nonvanishing :=
				hypotheses[0],
				hypotheses[1],
				hypotheses[2],
				hypotheses[3],
				hypotheses[4],
				hypotheses[5],
				hypotheses[6],
				hypotheses[7],
				hypotheses[8]
			fieldK := a.Unfolded(subfieldK, field.RingSubfieldDef)
			RS, RK := a.TermAs[RingOps[A]]("restrict_ring(R, S)"), a.TermAs[RingOps[A]]("restrict_ring(R, k)")
			powersOfD := a.TermAs[Set[A]]("monoid_powers(R.mul, R.one, d)")
			inclusion := a.TermAs[Fun[A, A]]("λx:A. x")
			φd := φ.Apply(d)
			φdInverse := inv.Apply(φd)
			localization := a.Have(
				"d being a unit of R = S[1/d], the inclusion of S into R is its localization at the powers of d",
				"is_localization_on(restrict_ring(R, S), monoid_powers(R.mul, R.one, d), R, λx:A. x)",
				By(ring, subringS, dInS, eInR, product, away, InclusionIsLocalizationAway.At(R, S, d, e)))
			targetRing := a.Have(
				"the target of φ is a commutative ring",
				"comm_ring_on(restrict_ring(R, k))",
				By(ring_homomorphism.Target.Read(ringMap)))
			imageInK := a.Have(
				"the image of d lies in k",
				"φ(d) ∈ k",
				By(dInS, ring_homomorphism.MapIn.Read(ringMap).AsFact().At(d)))
			imageUnit := a.Have(
				"φ(d) is a unit of k, its field inverse inverting it",
				"ring_unit(restrict_ring(R, k), φ(d))",
				Simp(Fwd(ring_ideal.RingUnitDef)),
				SplitConj(
					Case(
						"φ(d) lies in k",
						BySets(imageInK)),
					Case(
						"inv(φ(d)) lies in k, and φ(d) · inv(φ(d)) = one",
						Witness(φdInverse),
						By(
							imageInK,
							nonvanishing,
							field.InvIn.Read(fieldK).AsFact().At(φd),
							field.MulRightInverseOn.Read(fieldK).AsFact().At(φd))),
				))
			denominatorImagesUnits := a.Have(
				"φ sends every power of d to a unit of k",
				"∀q:A. q ∈ monoid_powers(R.mul, R.one, d) ⇒ ring_unit(restrict_ring(R, k), φ(q))",
				Derive(func(b *Argument) {
					b.FixAs[A]()
					premises := b.Assume()
					denominatorExpanded := b.Unfolded(premises, comm_monoid.MonoidPowersDef)
					n, denominatorExponent := b.ObtainAs[Nat](
						"choose the exponent presenting this denominator",
						"∃n:num. q = monoid_pow(R.mul, R.one, d, n)",
						BySets(denominatorExpanded))
					b.Show(
						"φ(q) = φ(d)ⁿ, and a power of a unit is a unit",
						By(
							denominatorExponent,
							dInS,
							imageUnit,
							ring_homomorphism.RingMapPower.Read(ringMap).AsFact().At(n, d),
							ring_ideal.RingUnitPow.Read(targetRing).At(φd, n)))
				}))
			ψ, extensionData := a.ObtainAs[Fun[A, A]](
				"extend φ to R by the universal property of the localization",
				"∃ψ:(A → A). ring_homomorphism(R, restrict_ring(R, k), ψ) ∧ (∀x:A. x ∈ S ⇒ ψ(x) = φ(x))",
				By(
					localization,
					ringMap,
					denominatorImagesUnits,
					ring_localization.LocalizationUniversal.At(RS, powersOfD, R, inclusion, RK, φ)))
			extension := a.Conjuncts(
				extensionData,
				"the extension is a ring homomorphism",
				"it agrees with φ on S")
			extensionFixesK := a.Have(
				"agreement on S makes the extension fix k",
				"∀c:A. c ∈ k ⇒ ψ(c) = c",
				BySets(kInS, extension[1], fixesK))
			kernel := a.TermAs[Set[A]]("ring_kernel(R.zero, R.carrier, ψ)")
			contraction := a.Have(
				"agreement identifies the contraction of the extension's kernel to S with the kernel of φ",
				"S ∩ ring_kernel(R.zero, R.carrier, ψ) = ring_kernel(R.zero, S, φ)",
				Simp(Fwd(ring_homomorphism.RingKernelDef)),
				BySets(comm_ring.SubringSubset.Read(subringS), extension[1]))
			generated := a.Have(
				"clearing denominators generates the kernel from its contraction",
				"ideal_span(R, S ∩ ring_kernel(R.zero, R.carrier, ψ)) = ring_kernel(R.zero, R.carrier, ψ)",
				By(
					ring,
					subringS,
					dInS,
					eInR,
					product,
					away,
					ring_homomorphism.KernelIdeal.Read(extension[0]),
					RingAwaySpanOfContraction.At(R, S, d, e, kernel)))
			a.Show(
				"the extension is a ring map agreeing with φ and fixing k, "+
					"its kernel generated by and contracting to the kernel of φ",
				Witness(ψ),
				By(extension[0], extension[1], extensionFixesK, generated, contraction))
		}),
})}

// KernelSpanAwayFieldResidues — a ring map φ : S → k fixing the field k
// that does not vanish at d: the ideal ker φ generates in S[1/d], here R,
// is the ideal of a k-rational point of R — proper, each member of R
// congruent modulo it to a member of k — and it meets S in ker φ. It is the
// kernel of the extension ψ : R → k of φ (HomomorphismExtendsAway), a ring
// map fixing k, and the kernel of such a map is the ideal of a k-rational
// point (KernelFieldResidues, read at R as the subring on its own carrier).
var KernelSpanAwayFieldResidues = kernelSpanAwayFieldResiduesThm{family.Add(registry.ProofEntry{
	Name: "KernelSpanAwayFieldResidues",
	Key:  "prop_6d71b31cb53c24c4",
	Build: family.Theorem(Statement{
		Binders: "∀R:ring_ops(A). ∀k:set(A). ∀inv:(A → A). ∀S:set(A). ∀d e:A. ∀φ:(A → A).",
		Hypotheses: []string{
			"comm_ring_on(R)",
			"ring_subfield(R, inv, k)",
			"subring(R, S)",
			"k ⊆ S",
			"d ∈ S",
			"e ∈ R.carrier",
			"d * e = R.one",
			"R.carrier = ring_away(R, S, d)",
			"ring_homomorphism(restrict_ring(R, S), restrict_ring(R, k), φ)",
			"∀c:A. c ∈ k ⇒ φ(c) = c",
			"φ(d) ≠ R.zero",
		},
		Conclusion: "rational_ideal(R, k, R.carrier, «kernelSpan») ∧ " +
			"S ∩ «kernelSpan» = ring_kernel(R.zero, S, φ)",
		Abbrev: Abbrev{
			{Name: "kernelSpan", Text: "ideal_span(R, ring_kernel(R.zero, S, φ))"},
		},
	},
		func(
			a *Argument,
			R *Expr[RingOps[A]],
			ring comm_ring.CommRingFact[on.R],
			k *Expr[Set[A]],
			inv *Arrow[A, A],
			subfieldK Fact,
			S *Expr[Set[A]],
			d, e *Expr[A],
			φ *Arrow[A, A],
			given Fact,
		) {
			hypotheses := a.Conjuncts(
				given,
				"S is a subring of R",
				"k lies in S",
				"d lies in S",
				"e lies in R",
				"d · e = one",
				"R is S with d inverted",
				"φ is a ring map from S to k",
				"φ fixes k",
				"φ does not vanish at d")
			subringS, kInS := hypotheses[0], hypotheses[1]
			ψ, extensionData := a.ObtainAs[Fun[A, A]](
				"extend φ to R across the localization",
				"∃ψ:(A → A). "+
					"    ring_homomorphism(R, restrict_ring(R, k), ψ) ∧ "+
					"    (∀x:A. x ∈ S ⇒ ψ(x) = φ(x)) ∧ "+
					"    (∀c:A. c ∈ k ⇒ ψ(c) = c) ∧ "+
					"    «kernelSpan» = ring_kernel(R.zero, R.carrier, ψ) ∧ "+
					"    S ∩ ring_kernel(R.zero, R.carrier, ψ) = ring_kernel(R.zero, S, φ)",
				By(ring, subfieldK, given, HomomorphismExtendsAway.At(R, k, inv, S, d, e, φ)))
			extension := a.Conjuncts(
				extensionData,
				"the extension is a ring homomorphism",
				"it agrees with φ on S",
				"it fixes k",
				"its kernel is the ideal the kernel of φ generates",
				"that kernel meets S in the kernel of φ")
			extensionRestricted := a.Have(
				"read R as its restriction to its own carrier",
				"ring_homomorphism(restrict_ring(R, R.carrier), restrict_ring(R, k), ψ)",
				Simp(Fwd(module_record.RestrictRingCarrier)),
				By(extension[0]))
			kInR := a.Have(
				"k lies in R through S",
				"k ⊆ R.carrier",
				BySets(comm_ring.SubringSubset.Read(subringS), kInS))
			kernelResidues := a.Have(
				"the kernel of the extension is the ideal of a k-rational point of R",
				"rational_ideal(R, k, R.carrier, ring_kernel(R.zero, R.carrier, ψ))",
				By(
					subfieldK,
					extensionRestricted,
					kInR,
					extension[2],
					quotient_ring.KernelFieldResidues.At(R, k, inv, a.TermAs[Set[A]]("R.carrier"), ψ)))
			a.Show(
				"the ideal the kernel of φ generates is the kernel of the extension: "+
					"the ideal of a k-rational point of R, meeting S in the kernel of φ",
				extension[3].Rw(),
				By(kernelResidues, extension[4]))
		}),
})}

// IndependentAway —independence over a ring S inside the field survives
// inverting a nonzero member t of S: one power tᵐ clears the denominators
// of a vanishing combination with coefficients in S[1/t], the cleared
// combination vanishes and has its coefficients in S, so they are zero,
// and inv(t)ᵐ undoes the power.
var IndependentAway = independentAwayThm{family.Add(registry.ProofEntry{
	Name: "IndependentAway",
	Key:  "prop_1e00315dd0f2e87b",
	Build: family.Theorem(Statement{
		Binders: "∀L:field_on(A). ∀S:set(A). ∀t:A. ∀E:set(A).",
		Hypotheses: []string{
			"subring(field_ring(L), S)",
			"t ∈ S",
			"t ≠ L.zero",
			"module_independent(restrict_ring(field_ring(L), S), regular_module(field_ring(L)), E)",
		},
		Conclusion: "module_independent(restrict_ring(field_ring(L), ring_away(field_ring(L), S, t)), " +
			"    regular_module(field_ring(L)), " +
			"    E)",
		Abbrev: Abbrev{
			{Name: "away", Text: "ring_away(field_ring(L), S, t)"},
		},
	},
		func(a *Argument, L field.FieldFact[on.L], S *Expr[Set[A]], t *Expr[A], E *Expr[Set[A]], h Fact) {
			parts := a.Conjuncts(
				h,
				"S is a subring of L",
				"t lies in S",
				"t is not zero",
				"E is independent over S")
			subringS, tInS, tNonzero, independent := parts[0], parts[1], parts[2], parts[3]
			free := a.Conjuncts(
				a.Unfolded(independent, linear_independence.ModuleIndependentDef),
				"E lies in L",
				"a vanishing combination of E over S has zero coefficients")
			ringL := field.RingOn.Read(L)
			ringS := a.Have(
				"S is a ring under L's operations",
				"comm_ring_on(restrict_ring(field_ring(L), S))",
				By(subringS, comm_ring.SubringRingOn.Read(ringL).At(S)))
			powersL, powersS := comm_ring.MulMonoidOn.Read(ringL), comm_ring.MulMonoidOn.Read(ringS)
			tInL := a.Have(
				"t lies in L",
				"t ∈ L.carrier",
				BySets(tInS, comm_ring.SubringSubset.Read(subringS)))
			tL, tS := a.MemberOf[on.L](t, tInL), proof.MemberOf(t, tInS)
			fieldRing := a.TermAs[RingOps[A]]("field_ring(L)")
			between := a.Have(
				"S[1/t] is a ring lying between S and L",
				"S ⊆ «away» ∧ subring(field_ring(L), «away»)",
				By(ringL, subringS, tInS, RingAwaySubring.At(fieldRing, S, t)))
			awaySubring := a.Conjuncts(
				between,
				"S lies in S[1/t]",
				"S[1/t] is a subring of L")[1]
			awayInL := a.Have(
				"S[1/t] lies in L",
				"«away» ⊆ L.carrier",
				By(comm_ring.SubringSubset.Read(awaySubring)))
			overAway := a.Have(
				"so L is a module over S[1/t]",
				"module_on(restrict_ring(field_ring(L), «away»), regular_module(field_ring(L)))",
				By(between, fractional_ideal.FieldModuleOn.Read(L).At(a.TermAs[Set[A]]("«away»"))))

			vanishing := a.Have(
				"a vanishing combination of E with coefficients in S[1/t] has zero coefficients",
				"∀T:set(A). ∀c:(A → A). "+
					"    finite(T) ∧ "+
					"    T ⊆ E ∧ "+
					"    (∀x:A. x ∈ T ⇒ c(x) ∈ «away») ∧ "+
					"    module_sum(L.add, L.zero, T, λx:A. c(x) * x) = L.zero ⇒ "+
					"    ∀x:A. x ∈ T ⇒ c(x) = L.zero",
				Derive(func(b *Argument) {
					T, c := b.FixAs[Set[A]](), b.FixAs[Fun[A, A]]()
					combination := b.Conjuncts(
						b.Assume(),
						"T is finite",
						"T lies in E",
						"its coefficients lie in S[1/t]",
						"it vanishes")
					m, beyond := b.ObtainAs[Nat](
						"from one exponent on, the powers of t bring every coefficient into S",
						"∃m:num. ∀k:num. m ≤ k ⇒ ∀x:A. x ∈ T ⇒ monoid_pow(L.mul, L.one, t, k) * c(x) ∈ S",
						By(
							subringS,
							fractional_ideal.FieldModuleOn.Read(L).At(S),
							fractional_ideal.SubringSubmodule.Read(L).At(S),
							tInS,
							combination[0],
							combination[2],
							b.Simplified(
								principal_ideal_domain.SaturationCommonExponent.At(
									b.TermAs[RingOps[A]]("restrict_ring(field_ring(L), S)"),
									b.TermAs[ModuleOps[A, A]]("regular_module(field_ring(L))"),
									t,
									S,
									T,
									c),
								Fwd(SaturationIsAway))),
						Named("m"))
					cleared := b.Have(
						"tᵐ does, in particular",
						"∀x:A. x ∈ T ⇒ monoid_pow(L.mul, L.one, t, m) * c(x) ∈ S",
						By(beyond.At(m), nat_order.LessEqRefl.At(m)))
					tmL := comm_monoid.PowIn.Read(powersL).At(tL, m)
					tmAway := b.Have(
						"tᵐ lies in S, so in S[1/t]",
						"monoid_pow(L.mul, L.one, t, m) ∈ «away»",
						BySets(comm_monoid.PowIn.Read(powersS).At(tS, m), between))
					supportInL := b.Have(
						"T lies in L",
						"T ⊆ L.carrier",
						BySets(combination[1], free[0]))
					scaled := b.Have(
						"the cleared combination vanishes",
						"module_sum(L.add, L.zero, T, λx:A.(monoid_pow(L.mul, L.one, t, m) * c(x)) * x) = L.zero",
						CalcEq(
							Leg(
								b.Term("monoid_pow(L.mul, L.one, t, m) * module_sum(L.add, L.zero, T, λx:A. c(x) * x)"),
								"tᵐ comes out of the combination",
								By(
									combination[0],
									supportInL,
									tmAway,
									combination[2],
									linear_independence.CombinationScale.Read(overAway).At(
										T, proof.MemberOf(b.TermAs[A]("monoid_pow(L.mul, L.one, t, m)"), tmAway), c))),
							Leg(
								b.Term("monoid_pow(L.mul, L.one, t, m) * L.zero"),
								"the combination vanishes",
								By(combination[3])),
							FinalLeg(
								"and zero absorbs tᵐ",
								By(comm_ring.MulRightZeroOn.Read(ringL).At(tmL))),
						))
					zeroes := b.Have(
						"so every tᵐ · c(x) is zero, E being independent over S",
						"∀x:A. x ∈ T ⇒ monoid_pow(L.mul, L.one, t, m) * c(x) = L.zero",
						By(
							combination[0],
							combination[1],
							cleared,
							scaled,
							free[1].At(T, b.TermAs[Fun[A, A]]("λx:A. monoid_pow(L.mul, L.one, t, m) * c(x)"))))
					invT := field.InvIn.Read(L).At(tL)
					inverse := b.Have(
						"inv(t) inverts t",
						"L.inv(t) * t = L.one",
						By(tInL, tNonzero, field.MulLeftInverseOn.Read(L).At(tL)))
					unit := b.Have(
						"so inv(t)ᵐ inverts tᵐ",
						"monoid_pow(L.mul, L.one, L.inv(t), m) * monoid_pow(L.mul, L.one, t, m) = L.one",
						By(comm_monoid.PowInverseOn.Read(powersL).At(invT, tL, m), inverse))
					x := b.FixAs[A]("x")
					inT := b.Assume()
					xL := b.Have(
						"c(x) lies in L",
						"c(x) ∈ L.carrier",
						BySets(inT, combination[2], awayInL))
					xZero := b.Have(
						"tᵐ · c(x) is zero",
						"monoid_pow(L.mul, L.one, t, m) * c(x) = L.zero",
						By(inT, zeroes.At(x)))
					b.Show(
						"so c(x) = inv(t)ᵐ · (tᵐ · c(x)) = zero",
						ByArith(
							ringL,
							xL,
							tmL,
							comm_monoid.PowIn.Read(powersL).At(invT, m),
							Scaled(b.Term("monoid_pow(L.mul, L.one, L.inv(t), m)"), xZero),
							Scaled(b.Term("c(x)"), unit)))
				}))
			a.Show(
				"so E is independent over S[1/t]",
				By(free[0], vanishing, linear_independence.ModuleIndependentDef))
		}),
})}

// SpanningAway — inside a field, a set E spanning a ring C over a subring S
// spans C[1/t] over S[1/t], for a nonzero t of S: a member v of C[1/t] has
// tⁿ · v a combination Σ p(x) · x over S, so v is the combination with the
// coefficients inv(t)ⁿ · p(x) of S[1/t].
var SpanningAway = spanningAwayThm{family.Add(registry.ProofEntry{
	Name: "SpanningAway",
	Key:  "prop_8769d6c94749f627",
	Build: family.Theorem(Statement{
		Binders: "∀L:field_on(A). ∀S C:set(A). ∀t:A. ∀E:set(A).",
		Hypotheses: []string{
			"subring(field_ring(L), S)",
			"subring(field_ring(L), C)",
			"S ⊆ C",
			"t ∈ S",
			"t ≠ L.zero",
			"E ⊆ C",
			"module_span(restrict_ring(field_ring(L), S), " +
				"    restrict_module(regular_module(field_ring(L)), C), " +
				"    E) = " +
				"C",
		},
		Conclusion: "«span» = «vectors»",
		Abbrev: Abbrev{
			{Name: "scalars", Text: "ring_away(field_ring(L), S, t)"},
			{Name: "vectors", Text: "ring_away(field_ring(L), C, t)"},
			{Name: "scalarRing", Text: "restrict_ring(field_ring(L), «scalars»)"},
			{Name: "vectorModule", Text: "restrict_module(regular_module(field_ring(L)), «vectors»)"},
			{Name: "span", Text: "module_span(«scalarRing», «vectorModule», E)"},
		},
	},
		func(
			a *Argument,
			L field.FieldFact[on.L],
			S, C *Expr[Set[A]],
			t *Expr[A],
			E *Expr[Set[A]],
			subringS, subringC, sInC, tInS, nonzero, eInC, spansC Fact,
		) {
			ringL := field.RingOn.Read(L)
			powersL := comm_ring.MulMonoidOn.Read(ringL)
			cInL := a.Have(
				"C lies in L",
				"C ⊆ L.carrier",
				By(comm_ring.SubringSubset.Read(subringC)))
			ringC := a.Have(
				"C is a ring under L's operations",
				"comm_ring_on(restrict_ring(field_ring(L), C))",
				By(subringC, comm_ring.SubringRingOn.Read(ringL).At(C)))
			tInC := a.Have(
				"t lies in C",
				"t ∈ C",
				BySets(tInS, sInC))
			tm := a.MemberOf[on.L](t, a.Have(
				"t lies in L",
				"t ∈ L.carrier",
				BySets(tInC, cInL)))
			invT := field.InvIn.Read(L).At(tm)
			fieldRing := a.TermAs[RingOps[A]]("field_ring(L)")
			away := a.Conjuncts(
				a.Have(
					"S[1/t] is a ring between S and L holding inv(t)",
					"S ⊆ «scalars» ∧ subring(field_ring(L), «scalars») ∧ L.inv(t) ∈ «scalars»",
					By(
						ringL,
						subringS,
						tInS,
						invT,
						nonzero,
						field.MulRightInverseOn.Read(L).At(tm),
						RingAwaySubring.At(fieldRing, S, t))),
				"S lies in S[1/t]",
				"S[1/t] is a subring of L",
				"inv(t) lies in S[1/t]")
			sInScalars, invInScalars := away[0], away[2]
			scalarSet, vectorSet := a.TermAs[Set[A]]("«scalars»"), a.TermAs[Set[A]]("«vectors»")
			ringScalars := a.Have(
				"S[1/t] is a ring under L's operations",
				"comm_ring_on(«scalarRing»)",
				By(away[1], comm_ring.SubringRingOn.Read(ringL).At(scalarSet)))
			chart := a.Conjuncts(
				a.Have(
					"C[1/t] is a ring between C and L",
					"C ⊆ «vectors» ∧ subring(field_ring(L), «vectors»)",
					By(ringL, subringC, tInC, RingAwaySubring.At(fieldRing, C, t))),
				"C lies in C[1/t]",
				"C[1/t] is a subring of L")
			cInVectors := chart[0]
			ringVectors := a.Have(
				"C[1/t] is a ring under L's operations",
				"comm_ring_on(restrict_ring(field_ring(L), «vectors»))",
				By(chart[1], comm_ring.SubringRingOn.Read(ringL).At(vectorSet)))
			scalarsInVectors := a.Have(
				"S[1/t] lies in C[1/t], S lying in C",
				"«scalars» ⊆ «vectors»",
				Unfold(RingAwayDef),
				BySets(sInC))
			eInVectors := a.Have(
				"E lies in C[1/t]",
				"E ⊆ «vectors»",
				BySets(eInC, cInVectors))

			nestedS := a.Have(
				"S under C's operations is S under the field's",
				"restrict_ring(restrict_ring(field_ring(L), C), S) = restrict_ring(field_ring(L), S)",
				Cite(module_record.RestrictRingTwice))
			nestedScalars := a.Have(
				"S[1/t] under C[1/t]'s operations is S[1/t] under the field's",
				"restrict_ring(restrict_ring(field_ring(L), «vectors»), «scalars») = «scalarRing»",
				Cite(module_record.RestrictRingTwice))
			subringSInC := a.Have(
				"S is a subring of C",
				"subring(restrict_ring(field_ring(L), C), S)",
				By(subringS, sInC, comm_ring.SubringRestrict.At(fieldRing, S, C)))
			subringScalarsInVectors := a.Have(
				"and S[1/t] a subring of C[1/t]",
				"subring(restrict_ring(field_ring(L), «vectors»), «scalars»)",
				By(away[1], scalarsInVectors, comm_ring.SubringRestrict.At(fieldRing, scalarSet, vectorSet)))
			overS := a.Have(
				"C is a module over its subring S",
				"module_on(restrict_ring(field_ring(L), S), restrict_module(regular_module(field_ring(L)), C))",
				nestedS.RwRev(),
				Simp(Rev(module_record.RegularModuleRestrict)),
				By(subringSInC, module.RegularModuleOverSubring.Read(ringC).At(S)))
			overScalars := a.Have(
				"C[1/t] is a module over its subring S[1/t]",
				"module_on(«scalarRing», «vectorModule»)",
				nestedScalars.RwRev(),
				Simp(Rev(module_record.RegularModuleRestrict)),
				By(subringScalarsInVectors, module.RegularModuleOverSubring.Read(ringVectors).At(scalarSet)))
			spanned := a.Have(
				"every member v of C[1/t] is a combination of E over S[1/t]",
				"∀v:A. v ∈ «vectors» ⇒ v ∈ «span»",
				Derive(func(b *Argument) {
					v := b.FixAs[A]("v")
					member := b.Assume()
					opened := b.Conjuncts(
						b.Have(
							"so v lies in L and a power of t brings it into C",
							"v ∈ L.carrier ∧ (∃n:num. monoid_pow(L.mul, L.one, t, n) * v ∈ C)",
							By(RingAwayMember.At(fieldRing, C, t, v), member)),
						"v lies in L",
						"a power of t brings v into C")
					n, cleared := b.UnpackAs[Nat](opened[1], "n")
					inSpan := b.Have(
						"tⁿ · v lies in C, the span of E over S",
						"monoid_pow(L.mul, L.one, t, n) * v ∈ "+
							"module_span(restrict_ring(field_ring(L), S), "+
							"    restrict_module(regular_module(field_ring(L)), C), "+
							"    E)",
						spansC.Rw(),
						By(cleared))
					T, p, combination := b.Obtain2As[Set[A], Fun[A, A]](
						"so tⁿ · v is a combination Σ p(x) · x of E over S",
						"∃T:set(A). ∃p:(A → A). "+
							"    finite(T) ∧ "+
							"    T ⊆ E ∧ "+
							"    (∀x:A. x ∈ T ⇒ p(x) ∈ S) ∧ "+
							"    monoid_pow(L.mul, L.one, t, n) * v = module_sum(L.add, L.zero, T, λx:A. p(x) * x)",
						By(
							inSpan,
							eInC,
							linear_independence.SpanMembership.Read(overS).At(
								E, b.TermAs[A]("monoid_pow(L.mul, L.one, t, n) * v"))))
					combo := b.Conjuncts(
						combination,
						"T is finite",
						"T lies in E",
						"the coefficients p(x) lie in S",
						"tⁿ · v = Σ p(x) · x")
					powersScalars := comm_ring.MulMonoidOn.Read(ringScalars)
					invPower := comm_monoid.PowIn.Read(powersScalars).At(
						proof.MemberOf(b.TermAs[A]("L.inv(t)"), invInScalars), n)
					coefficients := b.Have(
						"each p(x) lies in S[1/t]",
						"∀x:A. x ∈ T ⇒ p(x) ∈ «scalars»",
						Derive(func(c *Argument) {
							x := c.FixAs[A]("x")
							inT := c.Assume()
							c.Show(
								"S lying in S[1/t]",
								BySets(inT, combo[2].At(x), sInScalars))
						}))
					scaled := b.Have(
						"and so does each inv(t)ⁿ · p(x)",
						"∀x:A. x ∈ T ⇒ monoid_pow(L.mul, L.one, L.inv(t), n) * p(x) ∈ «scalars»",
						Derive(func(c *Argument) {
							x := c.FixAs[A]("x")
							inT := c.Assume()
							c.Show(
								"a product of members of S[1/t]",
								By(comm_ring.MulIn.Read(ringScalars), invPower, inT, coefficients.At(x)))
						}))
					supportInVectors := b.Have(
						"T lies in C[1/t]",
						"T ⊆ «vectors»",
						BySets(combo[1], eInVectors))
					unit := b.Have(
						"inv(t)ⁿ · tⁿ = one, inv(t) · t being one",
						"monoid_pow(L.mul, L.one, L.inv(t), n) * monoid_pow(L.mul, L.one, t, n) = L.one",
						By(
							comm_monoid.PowInverseOn.Read(powersL).At(invT, tm, n),
							nonzero,
							field.MulLeftInverseOn.Read(L).At(tm)))
					expansion := b.Have(
						"so v is the combination with the coefficients inv(t)ⁿ · p(x)",
						"v = module_sum(L.add, L.zero, T, λx:A. (monoid_pow(L.mul, L.one, L.inv(t), n) * p(x)) * x)",
						CalcEq(
							Leg(
								b.Term("monoid_pow(L.mul, L.one, L.inv(t), n) * (monoid_pow(L.mul, L.one, t, n) * v)"),
								"inv(t)ⁿ undoes tⁿ",
								ByArith(
									ringL,
									opened[0],
									comm_monoid.PowIn.Read(powersL).At(tm, n),
									comm_monoid.PowIn.Read(powersL).At(invT, n),
									Scaled(b.Term("v"), unit))),
							Leg(
								b.Term("monoid_pow(L.mul, L.one, L.inv(t), n) * module_sum(L.add, L.zero, T, λx:A. p(x) * x)"),
								"tⁿ · v is the combination over S",
								combo[3].Rw(),
								Basic()),
							FinalLeg(
								"inv(t)ⁿ comes inside the combination",
								By(
									combo[0],
									supportInVectors,
									coefficients,
									linear_independence.CombinationScale.Read(overScalars).At(T, invPower, p))),
						))
					witnessed := b.Have(
						"v is a combination of E over S[1/t]",
						"∃T:set(A). ∃c:(A → A). "+
							"    finite(T) ∧ "+
							"    T ⊆ E ∧ "+
							"    (∀x:A. x ∈ T ⇒ c(x) ∈ «scalars») ∧ "+
							"    v = module_sum(L.add, L.zero, T, λx:A. c(x) * x)",
						Derive(func(c *Argument) {
							c.Take(T)
							c.Take(c.TermAs[Fun[A, A]]("λx:A. monoid_pow(L.mul, L.one, L.inv(t), n) * p(x)"))
							c.Show(
								"at T and the coefficients inv(t)ⁿ · p(x)",
								By(combo[0], combo[1], scaled, expansion))
						}))
					b.Show(
						"so v lies in the span of E over S[1/t]",
						By(eInVectors, witnessed, linear_independence.SpanMembership.Read(overScalars).At(E, v)))
				}))
			spanSubmodule := a.Have(
				"the span of E over S[1/t] is a submodule of C[1/t]",
				"submodule(«scalarRing», «vectorModule», «span»)",
				By(eInVectors, submodule.SpanSubmodule.Read(overScalars).At(E)))
			a.Show(
				"so E spans C[1/t] over S[1/t]",
				By(
					submodule.SubmoduleSubset.Read(spanSubmodule),
					spanned,
					set_basic.SubsetDef,
					set_order.SubsetAntisym))
		}),
})}

// BasisAway — inside a field, a basis E of a ring C over a subring S is a
// basis of C[1/t] over S[1/t], for a nonzero t of S: E stays independent
// (IndependentAway) and spanning (SpanningAway).
var BasisAway = basisAwayThm{family.Add(registry.ProofEntry{
	Name: "BasisAway",
	Key:  "prop_ab47ff4cf70f306",
	Build: family.Theorem(Statement{
		Binders: "∀L:field_on(A). ∀S C:set(A). ∀t:A. ∀E:set(A).",
		Hypotheses: []string{
			"subring(field_ring(L), S)",
			"subring(field_ring(L), C)",
			"S ⊆ C",
			"t ∈ S",
			"t ≠ L.zero",
			"module_basis(restrict_ring(field_ring(L), S), " +
				"    restrict_module(regular_module(field_ring(L)), C), " +
				"    E)",
		},
		Conclusion: "module_basis(restrict_ring(field_ring(L), ring_away(field_ring(L), S, t)), " +
			"    restrict_module(regular_module(field_ring(L)), ring_away(field_ring(L), C, t)), " +
			"    E)",
		Abbrev: Abbrev{
			{Name: "scalars", Text: "ring_away(field_ring(L), S, t)"},
			{Name: "vectors", Text: "ring_away(field_ring(L), C, t)"},
			{Name: "scalarRing", Text: "restrict_ring(field_ring(L), «scalars»)"},
			{Name: "vectorModule", Text: "restrict_module(regular_module(field_ring(L)), «vectors»)"},
			{Name: "span", Text: "module_span(«scalarRing», «vectorModule», E)"},
		},
	},
		func(
			a *Argument,
			L field.FieldFact[on.L],
			S, C *Expr[Set[A]],
			t *Expr[A],
			E *Expr[Set[A]],
			h Fact,
		) {
			parts := a.Conjuncts(
				h,
				"S is a subring of L",
				"C is a subring of L",
				"S lies in C",
				"t lies in S",
				"t is not zero",
				"E is a basis of C over S")
			subringS, subringC, sInC, tInS, nonzero := parts[0], parts[1], parts[2], parts[3], parts[4]
			basis := a.Conjuncts(
				a.Unfolded(parts[5], linear_independence.ModuleBasisDef),
				"E is independent over S",
				"E spans C over S")
			free := a.Conjuncts(
				a.Unfolded(basis[0], linear_independence.ModuleIndependentDef),
				"E lies in C",
				"a vanishing combination of E over S has zero coefficients")

			ringL := field.RingOn.Read(L)
			cInL := a.Have(
				"C lies in L",
				"C ⊆ L.carrier",
				By(comm_ring.SubringSubset.Read(subringC)))
			tInC := a.Have(
				"t lies in C",
				"t ∈ C",
				BySets(tInS, sInC))
			fieldRing := a.TermAs[RingOps[A]]("field_ring(L)")
			cInVectors := a.Have(
				"C lies in C[1/t]",
				"C ⊆ «vectors»",
				By(ringL, subringC, tInC, RingAwaySubring.At(fieldRing, C, t)))
			eInVectors := a.Have(
				"E lies in C[1/t]",
				"E ⊆ «vectors»",
				BySets(free[0], cInVectors))

			// Independence: E is independent over S in L, so over S[1/t] in L
			// (IndependentAway), and a vanishing combination in C[1/t] is one
			// in L.
			inField := a.Have(
				"E is independent over S in L, its combinations being those of C",
				"module_independent(restrict_ring(field_ring(L), S), regular_module(field_ring(L)), E)",
				Unfold(linear_independence.ModuleIndependentDef),
				By(free[0], cInL, set_order.SubsetTrans, free[1]))
			awayInField := a.Unfolded(a.Have(
				"so E is independent over S[1/t] in L",
				"module_independent(«scalarRing», regular_module(field_ring(L)), E)",
				By(
					subringS,
					tInS,
					nonzero,
					inField,
					IndependentAway.Read(L).At(S, t, E))), linear_independence.ModuleIndependentDef)
			independent := a.Have(
				"and so in C[1/t]",
				"module_independent(«scalarRing», «vectorModule», E)",
				By(eInVectors, awayInField, linear_independence.ModuleIndependentDef))

			spans := a.Have(
				"and E spans C[1/t] over S[1/t]",
				"«span» = «vectors»",
				By(subringS, subringC, sInC, tInS, nonzero, free[0], basis[1], SpanningAway.Read(L).At(S, C, t, E)))
			a.Show(
				"so E is a basis of C[1/t] over S[1/t]",
				By(independent, spans, linear_independence.ModuleBasisDef))
		}),
})}

// CommonPower — one power of s serves a finite set: when a power of s ∈ S
// brings each member of a finite E ⊆ L into an S-submodule N of L, every
// power from one exponent on brings all of E into N. Each member of E lies
// in the saturation of N at s, and one exponent serves a finite family in a
// saturation, L being a module over S.
var CommonPower = commonPowerThm{family.Add(registry.ProofEntry{
	Name: "CommonPower",
	Key:  "prop_9dc687dffc1d9e5b",
	Build: family.Theorem(Statement{
		Binders: "∀L:field_on(A). ∀S N E:set(A). ∀s:A.",
		Hypotheses: []string{
			"subring(field_ring(L), S)",
			"s ∈ S",
			"submodule(restrict_ring(field_ring(L), S), regular_module(field_ring(L)), N)",
			"finite(E)",
			"E ⊆ L.carrier",
			"∀e:A. e ∈ E ⇒ ∃n:num. monoid_pow(L.mul, L.one, s, n) * e ∈ N",
		},
		Conclusion: "∃n:num. ∀m:num. n ≤ m ⇒ ∀e:A. e ∈ E ⇒ monoid_pow(L.mul, L.one, s, m) * e ∈ N",
	},
		func(
			a *Argument,
			L field.FieldFact[on.L],
			S, N, E *Expr[Set[A]],
			s *Expr[A],
			subringS, sInS, submoduleN, finiteE, eInL, eachBrought Fact,
		) {
			saturated := a.Have(
				"each member of E lies in the saturation of N at s",
				Statement{
					Binders:    "∀e:A.",
					Hypotheses: []string{"e ∈ E"},
					Conclusion: "e ∈ " +
						"module_saturation(restrict_ring(field_ring(L), S), regular_module(field_ring(L)), s, N)",
				},
				Simp(Fwd(principal_ideal_domain.ModuleSaturationMember)),
				BySets(eInL, eachBrought))
			a.Show(
				"so one exponent serves all of E, L being a module over S",
				By(
					subringS,
					sInS,
					submoduleN,
					finiteE,
					saturated,
					fractional_ideal.FieldModuleOn.Read(L).At(S),
					principal_ideal_domain.SaturationCommonExponent.At(
						a.TermAs[RingOps[A]]("restrict_ring(field_ring(L), S)"),
						a.TermAs[ModuleOps[A, A]]("regular_module(field_ring(L))"),
						s,
						N,
						E,
						a.TermAs[Fun[A, A]]("λe:A. e"))))
		}),
})}

// SaturationIsAway — the saturation of B at a inside the regular module of R
// is B with a inverted: the two definitions use the same power and product,
// and the scalars of the saturation enter only through R's operations.
var SaturationIsAway = saturationIsAwayThm{family.Add(registry.ProofEntry{
	Name: "SaturationIsAway",
	Key:  "prop_dc7b6c8b307e806a",
	Build: family.Theorem("∀R:ring_ops(A). ∀S B:set(A). ∀a:A. "+
		"    module_saturation(restrict_ring(R, S), regular_module(R), a, B) = ring_away(R, B, a)",
		func(a *Argument) {
			a.Show(
				"the two definitions use the same power and product",
				Simp(
					Fwd(principal_ideal_domain.ModuleSaturationDef),
					Fwd(RingAwayDef),
					Fwd(module_record.RestrictRingDef),
					Fwd(module_record.RegularModuleDef)),
				Basic())
		}),
})}

// SpanOverAwayIsSaturation — inside a field, an S-submodule X spans, over S
// with s inverted, exactly its saturation at s: the span holds s⁻ⁿx for each
// x in X, and the saturation holds X and is stable under S[1/s].
var SpanOverAwayIsSaturation = spanOverAwayIsSaturationThm{family.Add(registry.ProofEntry{
	Name: "SpanOverAwayIsSaturation",
	Key:  "prop_95a707e7baf8f32a",
	Reading: "s ≠ L.zero is load-bearing: at s = 0 every vector " +
		"saturates into X, while the span of X = {0} stays {0}.",
	Build: family.Theorem(Statement{
		Binders: "∀L:field_on(A). ∀S X:set(A). ∀s:A.",
		Hypotheses: []string{
			"subring(field_ring(L), S)",
			"s ∈ S",
			"s ≠ L.zero",
			"submodule(restrict_ring(field_ring(L), S), regular_module(field_ring(L)), X)",
		},
		Conclusion: "module_span(restrict_ring(field_ring(L), ring_away(field_ring(L), S, s)), " +
			"    regular_module(field_ring(L)), " +
			"    X) = " +
			"module_saturation(restrict_ring(field_ring(L), S), regular_module(field_ring(L)), s, X)",
		Abbrev: Abbrev{
			{Name: "away", Text: "ring_away(field_ring(L), S, s)"},
			{Name: "scalarsAway", Text: "restrict_ring(field_ring(L), «away»)"},
			{Name: "span", Text: "module_span(«scalarsAway», regular_module(field_ring(L)), X)"},
			{Name: "saturation", Text: "module_saturation(restrict_ring(field_ring(L), S), " +
				"    regular_module(field_ring(L)), " +
				"    s, " +
				"    X)"},
		},
	}, func(
		a *Argument,
		L field.FieldFact[on.L],
		S, X *Expr[Set[A]],
		s *Expr[A],
		subringS, sInS, nonzero, submoduleX Fact,
	) {
		ring := field.RingOn.Read(L)
		fieldRing := a.TermAs[RingOps[A]]("field_ring(L)")
		regular := a.TermAs[ModuleOps[A, A]]("regular_module(field_ring(L))")
		scalarsS := a.TermAs[RingOps[A]]("restrict_ring(field_ring(L), S)")
		awaySet := a.TermAs[Set[A]]("«away»")
		scalarsAway := a.TermAs[RingOps[A]]("«scalarsAway»")
		saturation := a.TermAs[Set[A]]("«saturation»")
		ringS := a.Have(
			"S is a ring under L's operations",
			"comm_ring_on(restrict_ring(field_ring(L), S))",
			By(subringS, comm_ring.SubringRingOn.Read(ring).At(S)))
		powersL, powersS := comm_ring.MulMonoidOn.Read(ring), comm_ring.MulMonoidOn.Read(ringS)
		powerL, powerS := comm_monoid.PowIn.Read(powersL), comm_monoid.PowIn.Read(powersS)
		sS := proof.MemberOf(s, sInS)
		sL := a.MemberOf[on.L](s, a.Have(
			"s lies in L",
			"s ∈ L.carrier",
			BySets(sInS, comm_ring.SubringSubset.Read(subringS))))
		invS := field.InvIn.Read(L).At(sL)
		between := a.Conjuncts(
			a.Have(
				"S[1/s] is a ring between S and L holding inv(s)",
				"S ⊆ «away» ∧ subring(field_ring(L), «away») ∧ L.inv(s) ∈ «away»",
				By(
					ring,
					subringS,
					sInS,
					invS,
					nonzero,
					field.MulRightInverseOn.Read(L).At(sL),
					RingAwaySubring.At(fieldRing, S, s))),
			"S lies in S[1/s]",
			"S[1/s] is a subring of L",
			"inv(s) lies in S[1/s]")
		overAway := a.Have(
			"L is a module over S[1/s]",
			"module_on(«scalarsAway», regular_module(field_ring(L)))",
			By(between[1], fractional_ideal.FieldModuleOn.Read(L).At(awaySet)))
		holdsX := a.Have(
			"the saturation holds X, at exponent zero",
			"X ⊆ «saturation»",
			By(
				subringS,
				fractional_ideal.FieldModuleOn.Read(L).At(S),
				submodule.SubmoduleSubset.Read(submoduleX),
				principal_ideal_domain.ModuleSaturationHolds.At(scalarsS, regular, s, X)))

		sums := a.Have(
			"exponents add across a sum",
			"∀u v:A. u ∈ «saturation» ∧ v ∈ «saturation» ⇒ u + v ∈ «saturation»",
			Derive(func(b *Argument) {
				u, v := b.FixAs[A]("u"), b.FixAs[A]("v")
				given := b.Conjuncts(
					b.Assume(),
					"u lies in the saturation",
					"so does v")
				first := b.Conjuncts(
					b.Simplified(given[0], Fwd(principal_ideal_domain.ModuleSaturationMember)),
					"u lies in L",
					"a power of s carries u into X")
				second := b.Conjuncts(
					b.Simplified(given[1], Fwd(principal_ideal_domain.ModuleSaturationMember)),
					"v lies in L",
					"a power of s carries v into X")
				um, vm := b.MemberOf[on.L](u, first[0]), b.MemberOf[on.L](v, second[0])
				n, uCleared := b.UnpackAs[Nat](first[1], "n")
				m, vCleared := b.UnpackAs[Nat](second[1], "m")
				sum := comm_ring.AddIn.Read(ring).At(um, vm)
				regroup := b.Have(
					"sⁿ⁺ᵐ (u + v) = sᵐ (sⁿ u) + sⁿ (sᵐ v)",
					"monoid_pow(L.mul, L.one, s, n + m) * (u + v) = "+
						"monoid_pow(L.mul, L.one, s, m) * (monoid_pow(L.mul, L.one, s, n) * u) + "+
						"monoid_pow(L.mul, L.one, s, n) * (monoid_pow(L.mul, L.one, s, m) * v)",
					ByArith(
						L,
						powerL.At(sL, n),
						powerL.At(sL, m),
						um,
						vm,
						sL,
						Scaled(sum, comm_monoid.PowAddOn.Read(powersL).AsFact().At(s, n, m))))
				sn, sm := powerS.At(sS, n), powerS.At(sS, m)
				carried := b.Have(
					"X holds both summands, its scalars being S",
					"monoid_pow(L.mul, L.one, s, n + m) * (u + v) ∈ X",
					By(
						regroup,
						uCleared,
						vCleared,
						sn,
						sm,
						submodule.SubmoduleSmul.At(
							scalarsS, regular, X, sm, b.TermAs[A]("monoid_pow(L.mul, L.one, s, n) * u")),
						submodule.SubmoduleSmul.At(
							scalarsS, regular, X, sn, b.TermAs[A]("monoid_pow(L.mul, L.one, s, m) * v")),
						submodule.SubmoduleAdd.Read(submoduleX)))
				b.Show(
					"so the sum lies in the saturation",
					Simp(Fwd(principal_ideal_domain.ModuleSaturationMember)),
					By(Normalized, carried, sum))
			}))
		scales := a.Have(
			"exponents add across a product",
			"∀c u:A. c ∈ «away» ∧ u ∈ «saturation» ⇒ c * u ∈ «saturation»",
			Derive(func(b *Argument) {
				c, u := b.FixAs[A]("c"), b.FixAs[A]("u")
				given := b.Conjuncts(
					b.Assume(),
					"c lies in S[1/s]",
					"u lies in the saturation")
				scalar := b.Conjuncts(
					b.Simplified(given[0], Fwd(RingAwayMember)),
					"c lies in L",
					"a power of s brings c into S")
				vector := b.Conjuncts(
					b.Simplified(given[1], Fwd(principal_ideal_domain.ModuleSaturationMember)),
					"u lies in L",
					"a power of s carries u into X")
				cm, um := b.MemberOf[on.L](c, scalar[0]), b.MemberOf[on.L](u, vector[0])
				k, cCleared := b.UnpackAs[Nat](scalar[1], "k")
				n, uCleared := b.UnpackAs[Nat](vector[1], "n")
				product := comm_ring.MulIn.Read(ring).At(cm, um)
				regroup := b.Have(
					"sᵏ⁺ⁿ (c u) = (sᵏ c) (sⁿ u)",
					"monoid_pow(L.mul, L.one, s, k + n) * (c * u) = "+
						"(monoid_pow(L.mul, L.one, s, k) * c) * (monoid_pow(L.mul, L.one, s, n) * u)",
					ByArith(
						L,
						powerL.At(sL, k),
						powerL.At(sL, n),
						cm,
						um,
						sL,
						Scaled(product, comm_monoid.PowAddOn.Read(powersL).AsFact().At(s, k, n))))
				carried := b.Have(
					"X holds that product, sᵏ c being a scalar of S",
					"monoid_pow(L.mul, L.one, s, k + n) * (c * u) ∈ X",
					By(
						regroup,
						submoduleX,
						cCleared,
						uCleared,
						submodule.SubmoduleSmul.At(
							scalarsS,
							regular,
							X,
							b.TermAs[A]("monoid_pow(L.mul, L.one, s, k) * c"),
							b.TermAs[A]("monoid_pow(L.mul, L.one, s, n) * u"))))
				b.Show(
					"so the product lies in the saturation",
					Simp(Fwd(principal_ideal_domain.ModuleSaturationMember)),
					By(Normalized, carried, product))
			}))
		inL := a.Have(
			"the saturation lies in L",
			"«saturation» ⊆ L.carrier",
			Unfold(set_basic.SubsetDef),
			a.ForEach(func(v *Expr[A]) Action {
				return By(principal_ideal_domain.ModuleSaturationMember.At(scalarsS, regular, s, X, v))
			}))
		saturationModule := a.Have(
			"so the saturation is a submodule over S[1/s]",
			"submodule(«scalarsAway», regular_module(field_ring(L)), «saturation»)",
			By(
				inL,
				holdsX,
				set_basic.SubsetDef,
				submodule.SubmoduleZero.Read(submoduleX),
				sums,
				scales,
				submodule.SubmoduleCriterion.Read(overAway).At(saturation)))
		spanInside := a.Have(
			"so the span of X lies in the saturation",
			"«span» ⊆ «saturation»",
			By(saturationModule, holdsX, submodule.SpanLeast.At(scalarsAway, regular, X, saturation)))

		ringAway := a.Have(
			"S[1/s] is a ring under L's operations",
			"comm_ring_on(«scalarsAway»)",
			By(between[1], comm_ring.SubringRingOn.Read(ring).At(awaySet)))
		powerAway := comm_monoid.PowIn.Read(comm_ring.MulMonoidOn.Read(ringAway))
		invAway := proof.MemberOf(a.TermAs[A]("L.inv(s)"), between[2])
		spanHoldsX := a.Unfolded(submodule.SubsetSpan.At(scalarsAway, regular, X), set_basic.SubsetDef)
		insideSpan := a.Have(
			"a vector of the saturation is a power of inv(s) times a member of X",
			"«saturation» ⊆ «span»",
			Unfold(set_basic.SubsetDef),
			Derive(func(b *Argument) {
				v := b.FixAs[A]("v")
				vector := b.Conjuncts(
					b.Simplified(b.Assume(), Fwd(principal_ideal_domain.ModuleSaturationMember)),
					"v lies in L",
					"a power of s carries v into X")
				vm := b.MemberOf[on.L](v, vector[0])
				n, cleared := b.UnpackAs[Nat](vector[1], "n")
				unit := b.Have(
					"inv(s)ⁿ inverts sⁿ",
					"monoid_pow(L.mul, L.one, L.inv(s), n) * monoid_pow(L.mul, L.one, s, n) = L.one",
					By(
						comm_monoid.PowInverseOn.Read(powersL).At(invS, sL, n),
						nonzero,
						field.MulLeftInverseOn.Read(L).At(sL)))
				recovered := b.Have(
					"so inv(s)ⁿ brings sⁿ v back to v",
					"monoid_pow(L.mul, L.one, L.inv(s), n) * (monoid_pow(L.mul, L.one, s, n) * v) = v",
					ByArith(L, powerL.At(invS, n), powerL.At(sL, n), vm, Scaled(v, unit)))
				image := b.TermAs[A]("monoid_pow(L.mul, L.one, s, n) * v")
				back := powerAway.At(invAway, n)
				b.Show(
					"and the span, a submodule over S[1/s] holding X, holds inv(s)ⁿ sⁿ v = v",
					By(
						recovered,
						cleared,
						spanHoldsX.At(image),
						back,
						submodule.SubmoduleSubset.Read(submoduleX),
						submodule.SpanSubmodule.Read(overAway).At(X),
						submodule.SubmoduleSmul.At(scalarsAway, regular, b.TermAs[Set[A]]("«span»"), back, image)))
			}))
		a.Show(
			"each side lies in the other",
			By(spanInside, insideSpan, set_order.SubsetAntisym))
	}),
})}

// AwayOfUnit — inverting what is already a unit of a subring changes nothing:
// its inverse powers undo the powers that clear a member.
var AwayOfUnit = awayOfUnitThm{family.Add(registry.ProofEntry{
	Name: "AwayOfUnit",
	Key:  "prop_c9622323b93d3f0e",
	Build: family.Theorem(Statement{
		Binders: "∀M:field_on(A). ∀S:set(A). ∀u v:A.",
		Hypotheses: []string{
			"subring(field_ring(M), S)",
			"u ∈ S",
			"v ∈ S",
			"u * v = M.one",
		},
		Conclusion: "ring_away(field_ring(M), S, u) = S",
	}, func(
		a *Argument,
		M field.FieldFact[on.M],
		S *Expr[Set[A]],
		u, v *Expr[A],
		subringS, uInS, vInS, inverse Fact,
	) {
		ring := field.RingOn.Read(M)
		powers := comm_ring.MulMonoidOn.Read(ring)
		inField := a.Have(
			"S lies in M",
			"S ⊆ M.carrier",
			By(comm_ring.SubringSubset.Read(subringS)))
		um := a.MemberOf[on.M](u, a.Have(
			"u lies in M",
			"u ∈ M.carrier",
			BySets(uInS, inField)))
		vm := a.MemberOf[on.M](v, a.Have(
			"v lies in M",
			"v ∈ M.carrier",
			BySets(vInS, inField)))
		onS := a.Have(
			"S is a ring under the operations of M",
			"comm_ring_on(restrict_ring(field_ring(M), S))",
			By(subringS, comm_ring.SubringRingOn.Read(ring).At(S)))
		a.Do(Simp(Fwd(set_basic.Extension)))
		r := a.FixAs[A]("r")
		a.Iff()
		a.Forward(
			"a power of v undoes the clearing",
			func(c *Argument, inAway Fact) {
				parts := c.Conjuncts(
					c.Simplified(inAway, Fwd(RingAwayMember)),
					"r lies in M",
					"a power of u brings r into S")
				rm := c.MemberOf[on.M](r, parts[0])
				n, cleared := c.UnpackAs[Nat](parts[1], "n")
				uPower := comm_monoid.PowIn.Read(powers).At(um, n)
				vPower := comm_monoid.PowIn.Read(powers).At(vm, n)
				cancels := c.Have(
					"The powers of u and v cancel",
					"monoid_pow(M.mul, M.one, u, n) * monoid_pow(M.mul, M.one, v, n) = M.one",
					By(inverse, um, vm, comm_monoid.PowInverseOn.Read(powers).At(um, vm, n)))
				undone := c.Have(
					"so the power of v undoes the clearing",
					"monoid_pow(M.mul, M.one, v, n) * (monoid_pow(M.mul, M.one, u, n) * r) = r",
					ByArith(ring, Scaled(r, cancels), uPower, vPower, rm))
				vInSPower := c.Have(
					"The power of v lies in S",
					"monoid_pow(M.mul, M.one, v, n) ∈ S",
					By(vInS, comm_monoid.PowIn.Read(comm_ring.MulMonoidOn.Read(onS)).AsFact().At(v, n)))
				product := c.Have(
					"so the product lies in S",
					"monoid_pow(M.mul, M.one, v, n) * (monoid_pow(M.mul, M.one, u, n) * r) ∈ S",
					By(
						subringS,
						vInSPower,
						cleared,
						comm_ring.SubringMul.At(
							c.TermAs[RingOps[A]]("field_ring(M)"),
							S,
							c.TermAs[A]("monoid_pow(M.mul, M.one, v, n)"),
							c.TermAs[A]("monoid_pow(M.mul, M.one, u, n) * r"))))
				c.Show(
					"which is r",
					By(Normalized, undone, product))
			})
		a.Backward(
			"the zeroth power clears a member of S",
			func(c *Argument, inS Fact) {
				rm := c.MemberOf[on.M](r, c.Have(
					"r lies in M",
					"r ∈ M.carrier",
					BySets(inS, inField)))
				oneTimes := c.Have(
					"One times r is r",
					"M.one * r = r",
					ByArith(ring, rm))
				clears := c.Have(
					"The zeroth power brings r into S",
					"∃n:num. monoid_pow(M.mul, M.one, u, n) * r ∈ S",
					Witness(c.TermAs[Nat]("0")),
					Simp(Fwd(comm_monoid.MonoidPowDef)),
					By(Normalized, inS, oneTimes))
				c.Show(
					"and r lies in M",
					Simp(Fwd(RingAwayMember)),
					By(rm, clears))
			})
	}),
})}

// RingAwayTwice — inverting x and then y in a subring is inverting x · y: the
// powers xᵐ⁺ⁿ and yᵐ⁺ⁿ of the product exceed what either step cleared, and the
// excess lies in the subring; conversely one exponent serves both steps.
var RingAwayTwice = ringAwayTwiceThm{family.Add(registry.ProofEntry{
	Name: "RingAwayTwice",
	Key:  "prop_dee66ad14dea0ba4",
	Build: family.Theorem(Statement{
		Binders: "∀M:field_on(A). ∀S:set(A). ∀x y:A.",
		Hypotheses: []string{
			"subring(field_ring(M), S)",
			"x ∈ S",
			"y ∈ S",
		},
		Conclusion: "ring_away(field_ring(M), ring_away(field_ring(M), S, x), y) = " +
			"ring_away(field_ring(M), S, x * y)",
	}, func(
		a *Argument,
		M field.FieldFact[on.M],
		S *Expr[Set[A]],
		x, y *Expr[A],
		subringS, xInS, yInS Fact,
	) {
		ring := field.RingOn.Read(M)
		powers := comm_ring.MulMonoidOn.Read(ring)
		inField := a.Have(
			"S lies in M",
			"S ⊆ M.carrier",
			By(comm_ring.SubringSubset.Read(subringS)))
		xm := a.MemberOf[on.M](x, a.Have(
			"x lies in M",
			"x ∈ M.carrier",
			BySets(xInS, inField)))
		ym := a.MemberOf[on.M](y, a.Have(
			"y lies in M",
			"y ∈ M.carrier",
			BySets(yInS, inField)))
		onS := a.Have(
			"S is a ring under the operations of M",
			"comm_ring_on(restrict_ring(field_ring(M), S))",
			By(subringS, comm_ring.SubringRingOn.Read(ring).At(S)))
		powersInS := comm_ring.MulMonoidOn.Read(onS)
		a.Do(Simp(Fwd(set_basic.Extension)))
		r := a.FixAs[A]("r")
		a.Iff()
		a.Forward(
			"the exponents add",
			func(c *Argument, inLeft Fact) {
				outer := c.Conjuncts(
					c.Simplified(inLeft, Fwd(RingAwayMember)),
					"r lies in M",
					"powers of y and x bring r into S")
				rm := c.MemberOf[on.M](r, outer[0])
				m, inner := c.UnpackAs[Nat](outer[1], "m")
				innerParts := c.Conjuncts(
					inner,
					"yᵐ · r lies in M",
					"a power of x brings it into S")
				n, cleared := c.UnpackAs[Nat](innerParts[1], "n")
				sum := c.TermAs[Nat]("m + n")
				expanded := c.Have(
					"The power of the product splits into what cleared r and the rest",
					"monoid_pow(M.mul, M.one, x * y, m + n) * r = "+
						"(monoid_pow(M.mul, M.one, x, m) * monoid_pow(M.mul, M.one, y, n)) * "+
						"(monoid_pow(M.mul, M.one, x, n) * (monoid_pow(M.mul, M.one, y, m) * r))",
					GroupPremises(xm, ym, comm_monoid.MulPowOn.Read(powers).AsFact().At(x, y, sum)).Rw(),
					GroupPremises(xm, comm_monoid.PowAddOn.Read(powers).AsFact().At(x, m, n)).Rw(),
					GroupPremises(ym, comm_monoid.PowAddOn.Read(powers).AsFact().At(y, m, n)).Rw(),
					ByArith(
						ring,
						xm,
						ym,
						rm,
						comm_monoid.PowIn.Read(powers).At(xm, m),
						comm_monoid.PowIn.Read(powers).At(xm, n),
						comm_monoid.PowIn.Read(powers).At(ym, m),
						comm_monoid.PowIn.Read(powers).At(ym, n)))
				inS := c.Have(
					"The rest lies in S, so the power of the product brings r into S",
					"(monoid_pow(M.mul, M.one, x, m) * monoid_pow(M.mul, M.one, y, n)) * "+
						"(monoid_pow(M.mul, M.one, x, n) * (monoid_pow(M.mul, M.one, y, m) * r)) ∈ "+
						"S",
					By(
						cleared,
						subringS,
						xInS,
						yInS,
						comm_monoid.PowIn.Read(powersInS).AsFact().At(x, m),
						comm_monoid.PowIn.Read(powersInS).AsFact().At(y, n),
						comm_ring.SubringMul.At(
							c.TermAs[RingOps[A]]("field_ring(M)"),
							S,
							c.TermAs[A]("monoid_pow(M.mul, M.one, x, m)"),
							c.TermAs[A]("monoid_pow(M.mul, M.one, y, n)")),
						comm_ring.SubringMul.At(
							c.TermAs[RingOps[A]]("field_ring(M)"),
							S,
							c.TermAs[A]("monoid_pow(M.mul, M.one, x, m) * monoid_pow(M.mul, M.one, y, n)"),
							c.TermAs[A]("monoid_pow(M.mul, M.one, x, n) * (monoid_pow(M.mul, M.one, y, m) * r)"))))
				clears := c.Have(
					"so a power of x · y brings r into S",
					"∃k:num. monoid_pow(M.mul, M.one, x * y, k) * r ∈ S",
					Witness(sum),
					By(expanded, inS))
				c.Show(
					"and r lies in S with x · y inverted",
					Simp(Fwd(RingAwayMember)),
					By(outer[0], clears))
			})
		a.Backward(
			"one exponent serves both steps",
			func(c *Argument, inRight Fact) {
				parts := c.Conjuncts(
					c.Simplified(inRight, Fwd(RingAwayMember)),
					"r lies in M",
					"a power of x · y brings r into S")
				rm := c.MemberOf[on.M](r, parts[0])
				n, cleared := c.UnpackAs[Nat](parts[1], "n")
				yPower := comm_monoid.PowIn.Read(powers).At(ym, n)
				xPower := comm_monoid.PowIn.Read(powers).At(xm, n)
				split := c.Have(
					"That power is the power of x on the power of y",
					"monoid_pow(M.mul, M.one, x * y, n) * r = "+
						"monoid_pow(M.mul, M.one, x, n) * (monoid_pow(M.mul, M.one, y, n) * r)",
					GroupPremises(xm, ym, comm_monoid.MulPowOn.Read(powers).AsFact().At(x, y, n)).Rw(),
					ByArith(ring, xPower, yPower, rm))
				expanded := c.Have(
					"so the power of x brings yⁿ · r into S",
					"monoid_pow(M.mul, M.one, x, n) * (monoid_pow(M.mul, M.one, y, n) * r) ∈ S",
					By(cleared, split))
				oneExponent := c.Have(
					"so the same exponent serves both steps",
					"∃j:num. "+
						"    monoid_pow(M.mul, M.one, y, j) * r ∈ M.carrier ∧ "+
						"    (∃h:num. monoid_pow(M.mul, M.one, x, h) * (monoid_pow(M.mul, M.one, y, j) * r) ∈ S)",
					Witness(n),
					By(expanded, comm_ring.MulIn.Read(ring).At(yPower, rm)))
				c.Show(
					"and r lies in S[1/x] with y inverted",
					Simp(Fwd(RingAwayMember)),
					By(parts[0], oneExponent))
			})
	}),
})}

// RingAwayUnitFactor — inverting c y in a subring is inverting y, when c is a unit of
// the subring: inverting c adds nothing (AwayOfUnit), and inverting c y is inverting
// c and then y (RingAwayTwice).
var RingAwayUnitFactor = ringAwayUnitFactorThm{family.Add(registry.ProofEntry{
	Name: "RingAwayUnitFactor",
	Key:  "prop_edaf76b205f594fe",
	Build: family.Theorem(Statement{
		Binders: "∀M:field_on(A). ∀S:set(A). ∀c e y:A.",
		Hypotheses: []string{
			"subring(field_ring(M), S)",
			"c ∈ S",
			"e ∈ S",
			"c * e = M.one",
			"y ∈ S",
		},
		Conclusion: "ring_away(field_ring(M), S, c * y) = ring_away(field_ring(M), S, y)",
	},
		func(
			a *Argument,
			M field.FieldFact[on.M],
			S *Expr[Set[A]],
			c, e, y *Expr[A],
			subringS, cIn, eIn, product, yIn Fact,
		) {
			inverted := a.Have(
				"inverting c adds nothing to S",
				"ring_away(field_ring(M), S, c) = S",
				By(M, subringS, cIn, eIn, product, At(Read(AwayOfUnit, M), S, c, e)))
			twice := a.Have(
				"inverting c y is inverting c and then y",
				"ring_away(field_ring(M), ring_away(field_ring(M), S, c), y) = ring_away(field_ring(M), S, c * y)",
				By(M, subringS, cIn, yIn, At(Read(RingAwayTwice, M), S, c, y)))
			a.Show(
				"and inverting c adds nothing",
				By(inverted, twice))
		}),
})}

// RingAwayInSubfield — let u be a nonzero element of a subring U of a field M, and
// L a subfield holding U. Then U[1/u] is a subring holding U and the inverse of u.
// It lies in L, a subring holding U and the inverse of u, and inverting u in it adds
// nothing, u being a unit of it (AwayOfUnit).
var RingAwayInSubfield = ringAwayInSubfieldThm{family.Add(registry.ProofEntry{
	Name: "RingAwayInSubfield",
	Key:  "prop_635394325047675a",
	Build: family.Theorem(Statement{
		Binders: "∀M:field_on(A). ∀U L:set(A). ∀u:A.",
		Hypotheses: []string{
			"subring(field_ring(M), U)",
			"subfield(M, L)",
			"U ⊆ L",
			"u ∈ U",
			"u ≠ M.zero",
		},
		Conclusion: "subring(field_ring(M), «C») ∧ " +
			"U ⊆ «C» ∧ " +
			"«C» ⊆ L ∧ " +
			"M.inv(u) ∈ «C» ∧ " +
			"ring_away(field_ring(M), «C», u) = «C»",
		Abbrev: Abbrev{
			{Name: "C", Text: "ring_away(field_ring(M), U, u)"},
		},
	}, func(
		arg *Argument,
		M field.FieldFact[on.M],
		U, L *Expr[Set[A]],
		u *Expr[A],
		subU, subL, inL, uIn, nonzero Fact,
	) {
		ring := field.RingOn.Read(M)
		R := arg.TermAs[RingOps[A]]("field_ring(M)")
		C := arg.TermAs[Set[A]]("«C»")
		uField := arg.Have(
			"u lies in M",
			"u ∈ M.carrier",
			BySets(uIn, subU, comm_ring.SubringSubset.At(R, U)))
		um := arg.MemberOf[on.M](u, uField)
		v := arg.TermAs[A]("M.inv(u)")
		vm := arg.MemberOf[on.M](v, field.InvIn.Read(M).At(um))
		inverse := arg.Have(
			"u times its inverse is one",
			"u * M.inv(u) = M.one",
			By(uField, nonzero, field.MulRightInverseOn.Read(M).AsFact().At(u)))
		away := arg.Conjuncts(
			arg.Have(
				"U[1/u] is a subring holding U and every inverse of u",
				"U ⊆ «C» ∧ subring(field_ring(M), «C») ∧ (∀w:A. w ∈ M.carrier ∧ u * w = M.one ⇒ w ∈ «C»)",
				By(ring, subU, uIn, At(RingAwaySubring, R, U, u))),
			"U lies in U[1/u]",
			"U[1/u] is a subring",
			"it holds the inverses of u")
		inC := away[0]
		subC := away[1]
		vInC := arg.Have(
			"so it holds the inverse of u",
			"M.inv(u) ∈ «C»",
			By(vm, inverse, away[2].At(v)))
		uInC := arg.Have(
			"and u",
			"u ∈ «C»",
			BySets(uIn, inC))
		subRingL := arg.Have(
			"L is a subring of M",
			"subring(field_ring(M), L)",
			By(subL, field.SubfieldSubring.Read(M).At(L)))
		uInL := arg.Have(
			"u lies in L",
			"u ∈ L",
			BySets(uIn, inL))
		vInL := arg.Have(
			"so does its inverse",
			"M.inv(u) ∈ L",
			By(subL, uInL, field.SubfieldInv.At(arg.TermAs[FieldOps[A]]("M"), L, u)))
		arg.Do(SplitConjAll(
			Case(
				"U[1/u] is a subring",
				By(subC)),
			Case(
				"U[1/u] holds U",
				By(inC)),
			Case(
				"U[1/u] lies in L, a subring holding U and the inverse of u",
				By(subRingL, inL, nonzero, vInL, RingAwayLeast.Read(M).At(U, L, um))),
			Case(
				"U[1/u] holds the inverse of u",
				By(vInC)),
			Case(
				"inverting u in U[1/u] adds nothing, u being a unit of it",
				By(subC, uInC, vInC, inverse, AwayOfUnit.Read(M).At(C, u, v)))))
	}),
})}

// RingAwayLeast — a subring Q of a field holding U and the inverse of a nonzero u
// holds U[1/u]: a member r is the product of uⁿ r, in U, by the power of the inverse
// of u.
var RingAwayLeast = ringAwayLeastThm{family.Add(registry.ProofEntry{
	Name: "RingAwayLeast",
	Key:  "prop_4f1173d29fcafad5",
	Build: family.Theorem(Statement{
		Binders: "∀M:field_on(A). ∀U Q:set(A). ∀u:A.",
		Hypotheses: []string{
			"subring(field_ring(M), Q)",
			"U ⊆ Q",
			"u ∈ M.carrier",
			"u ≠ M.zero",
			"M.inv(u) ∈ Q",
		},
		Conclusion: "ring_away(field_ring(M), U, u) ⊆ Q",
	}, func(
		arg *Argument,
		M field.FieldFact[on.M],
		U, Q *Expr[Set[A]],
		u *Expr[A],
		subQ, uInQ, uIn, nonzero, inverseIn Fact,
	) {
		ring := field.RingOn.Read(M)
		powers := comm_ring.MulMonoidOn.Read(ring)
		R := arg.TermAs[RingOps[A]]("field_ring(M)")
		inverse := arg.TermAs[A]("M.inv(u)")
		um := arg.MemberOf[on.M](u, uIn)
		inField := arg.Have(
			"Q lies in M",
			"Q ⊆ M.carrier",
			By(subQ, comm_ring.SubringSubset.At(R, Q)))
		invm := arg.MemberOf[on.M](inverse, arg.Have(
			"the inverse of u lies in M",
			"M.inv(u) ∈ M.carrier",
			BySets(inverseIn, inField)))
		ringQ := arg.Have(
			"Q is a ring",
			"comm_ring_on(restrict_ring(field_ring(M), Q))",
			By(subQ, comm_ring.SubringRingOn.Read(ring).At(Q)))
		pointwise := arg.Have(
			"a member of U[1/u] lies in Q",
			"∀r:A. r ∈ ring_away(field_ring(M), U, u) ⇒ r ∈ Q",
			Derive(func(b *Argument) {
				r := b.FixAs[A]("r")
				member := b.Conjuncts(
					b.Have(
						"r lies in M with a power of u carrying it into U",
						"r ∈ M.carrier ∧ ∃n:num. monoid_pow(M.mul, M.one, u, n) * r ∈ U",
						By(b.Assume(), RingAwayMember.At(R, U, u, r))),
					"r lies in M",
					"a power of u clears it")
				n, cleared := b.UnpackAs[Nat](member[1], "n")
				_, hIs := b.LetAs[A]("h", "monoid_pow(M.mul, M.one, u, n)")
				e, eIs := b.LetAs[A]("e", "monoid_pow(M.mul, M.one, M.inv(u), n)")
				hm := b.Have(
					"the power of u lies in M",
					"h ∈ M.carrier",
					By(Normalized, hIs, comm_monoid.PowIn.Read(powers).At(um, n)))
				em := b.Have(
					"so does the power of its inverse",
					"e ∈ M.carrier",
					By(Normalized, eIs, comm_monoid.PowIn.Read(powers).At(invm, n)))
				cancels := b.Have(
					"the two powers cancel",
					"h * e = M.one",
					By(
						Normalized,
						hIs,
						eIs,
						nonzero,
						field.MulRightInverseOn.Read(M).At(um),
						comm_monoid.PowInverseOn.Read(powers).At(um, invm, n)))
				eInQ := b.Have(
					"the power of the inverse lies in Q",
					"e ∈ Q",
					By(
						Normalized,
						eIs,
						inverseIn,
						comm_monoid.PowIn.Read(comm_ring.MulMonoidOn.Read(ringQ)).AsFact().At(inverse, n)))
				clearedIn := b.Have(
					"and h r lies in Q",
					"h * r ∈ Q",
					BySets(cleared, uInQ))
				regroup := b.Have(
					"r is the product of e and h r",
					"e * (h * r) = r",
					ByArith(ring, Scaled(r, cancels), em, hm, member[0]))
				b.Show(
					"which lies in Q",
					By(
						Normalized,
						regroup,
						subQ,
						eInQ,
						clearedIn,
						comm_ring.SubringMul.At(R, Q, e, b.TermAs[A]("h * r"))))
			}))
		arg.Show(
			"so U[1/u] lies in Q",
			BySets(pointwise))
	}),
})}

// CommonRingAway — let S and T be subrings of a field, T inside S[1/d] and S inside
// T[1/e] for nonzero d in S and e in T. Then S[1/h] = T[1/g] for nonzero h in S and
// g in T: with dⁿ e = x in S put h = d x, and with eᵐ h = y in T put g = e y. Each
// side, the least subring holding its ring and its inverse (RingAwayLeast), lies in
// the other once the other holds both: T[1/g] holds S, through T[1/e], and
// 1/h = eᵐ e/g; S[1/h] holds T, through S[1/d] with 1/d = x/h, and
// 1/g = (1/e)(1/eᵐ)(1/h) with 1/e = dⁿ d/h.
var CommonRingAway = commonRingAwayThm{family.Add(registry.ProofEntry{
	Name: "CommonRingAway",
	Key:  "prop_75c821b2e1c44514",
	Build: family.Theorem(Statement{
		Binders: "∀M:field_on(A). ∀S T:set(A). ∀d e:A.",
		Hypotheses: []string{
			"subring(field_ring(M), S)",
			"subring(field_ring(M), T)",
			"d ∈ S",
			"d ≠ M.zero",
			"e ∈ T",
			"e ≠ M.zero",
			"T ⊆ ring_away(field_ring(M), S, d)",
			"S ⊆ ring_away(field_ring(M), T, e)",
		},
		Conclusion: "∃h g:A. " +
			"    h ∈ S ∧ " +
			"    h ≠ M.zero ∧ " +
			"    g ∈ T ∧ " +
			"    g ≠ M.zero ∧ " +
			"    ring_away(field_ring(M), S, h) = ring_away(field_ring(M), T, g)",
	},
		func(
			arg *Argument,
			M field.FieldFact[on.M],
			S, T *Expr[Set[A]],
			d, e *Expr[A],
			subS, subT, dIn, dNonzero, eIn, eNonzero, tInAway, sInAway Fact,
		) {
			ring := field.RingOn.Read(M)
			powers := comm_ring.MulMonoidOn.Read(ring)
			R := arg.TermAs[RingOps[A]]("field_ring(M)")
			carrier := arg.TermAs[Set[A]]("M.carrier")
			n, cleared := arg.ObtainAs[Nat](
				"e lies in S[1/d], so a power of d carries it into S",
				"∃n:num. monoid_pow(M.mul, M.one, d, n) * e ∈ S",
				By(eIn, tInAway, RingAwayMember.At(R, S, d, e), set_basic.SubsetDef))
			x, xDef := arg.LetAs[A]("x", "monoid_pow(M.mul, M.one, d, n) * e")
			h, hDef := arg.LetAs[A]("h", "d * x")
			hIn := arg.Have(
				"h lies in S",
				"h ∈ S",
				By(hDef, dIn, cleared, subS, comm_ring.SubringDef))
			m, raised := arg.ObtainAs[Nat](
				"h lies in T[1/e], so a power of e carries it into T",
				"∃m:num. monoid_pow(M.mul, M.one, e, m) * h ∈ T",
				By(hIn, sInAway, RingAwayMember.At(R, T, e, h), set_basic.SubsetDef))
			y, yDef := arg.LetAs[A]("y", "monoid_pow(M.mul, M.one, e, m) * h")
			g, gDef := arg.LetAs[A]("g", "e * y")
			gIn := arg.Have(
				"g lies in T",
				"g ∈ T",
				By(gDef, eIn, raised, subT, comm_ring.SubringDef))
			inField := arg.Conjuncts(
				arg.Have(
					"all of them lie in M",
					"d ∈ M.carrier ∧ e ∈ M.carrier ∧ x ∈ M.carrier ∧ h ∈ M.carrier ∧ y ∈ M.carrier ∧ g ∈ M.carrier",
					BySets(
						dIn,
						eIn,
						cleared,
						hIn,
						raised,
						gIn,
						subS,
						subT,
						comm_ring.SubringSubset.At(R, S),
						comm_ring.SubringSubset.At(R, T))),
				"d lies in M",
				"e lies in M",
				"x lies in M",
				"h lies in M",
				"y lies in M",
				"g lies in M")
			dm := arg.MemberOf[on.M](d, inField[0])
			em := arg.MemberOf[on.M](e, inField[1])
			xm := arg.MemberOf[on.M](x, inField[2])
			hm := arg.MemberOf[on.M](h, inField[3])
			ym := arg.MemberOf[on.M](y, inField[4])
			gm := arg.MemberOf[on.M](g, inField[5])
			powerD := comm_monoid.PowIn.Read(powers).At(dm, n)
			powerE := comm_monoid.PowIn.Read(powers).At(em, m)
			nonzeroPowers := arg.Have(
				"no power of a nonzero element is zero: it times the power of the inverse is one",
				"∀a:A. ∀j:num. a ∈ M.carrier ∧ a ≠ M.zero ⇒ monoid_pow(M.mul, M.one, a, j) ≠ M.zero",
				Derive(func(b *Argument) {
					a := b.FixAs[A]("a")
					j := b.FixAs[Nat]("j")
					given := b.Conjuncts(
						b.Assume(),
						"a lies in M",
						"a is not zero")
					am := b.MemberOf[on.M](a, given[0])
					inverse := field.InvIn.Read(M).At(am)
					b.Show(
						"aʲ (1/a)ʲ = 1 and 0 (1/a)ʲ = 0",
						By(
							given[1],
							field.OneNotZeroOn.Read(M),
							field.MulRightInverseOn.Read(M).At(am),
							comm_monoid.PowInverseOn.Read(powers).At(am, inverse, j),
							comm_ring.MulLeftZeroOn.Read(ring).At(comm_monoid.PowIn.Read(powers).At(inverse, j))))
				}))
			xNonzero := arg.Have(
				"x is not zero",
				"x ≠ M.zero",
				By(xDef, eNonzero, dm, nonzeroPowers.At(d, n), dNonzero, field.MulEqZeroOn.Read(M).At(powerD, em)))
			hNonzero := arg.Have(
				"h is not zero",
				"h ≠ M.zero",
				By(Normalized, hDef, dNonzero, xNonzero, field.MulEqZeroOn.Read(M).At(dm, xm)))
			yNonzero := arg.Have(
				"y is not zero",
				"y ≠ M.zero",
				By(yDef, hNonzero, em, nonzeroPowers.At(e, m), eNonzero, field.MulEqZeroOn.Read(M).At(powerE, hm)))
			gNonzero := arg.Have(
				"g is not zero",
				"g ≠ M.zero",
				By(Normalized, gDef, eNonzero, yNonzero, field.MulEqZeroOn.Read(M).At(em, ym)))
			whole := field.CarrierSubfield.Read(M)
			awayS := arg.Conjuncts(
				arg.Have(
					"S[1/h] is a subring holding S and the inverse of h",
					"subring(field_ring(M), ring_away(field_ring(M), S, h)) ∧ "+
						"S ⊆ ring_away(field_ring(M), S, h) ∧ "+
						"M.inv(h) ∈ ring_away(field_ring(M), S, h)",
					By(
						whole,
						subS,
						hIn,
						hNonzero,
						comm_ring.SubringSubset.At(R, S),
						RingAwayInSubfield.Read(M).At(S, carrier, h))),
				"S[1/h] is a subring",
				"it holds S",
				"it holds 1/h")
			awayT := arg.Conjuncts(
				arg.Have(
					"T[1/g] is a subring holding T and the inverse of g",
					"subring(field_ring(M), ring_away(field_ring(M), T, g)) ∧ "+
						"T ⊆ ring_away(field_ring(M), T, g) ∧ "+
						"M.inv(g) ∈ ring_away(field_ring(M), T, g)",
					By(
						whole,
						subT,
						gIn,
						gNonzero,
						comm_ring.SubringSubset.At(R, T),
						RingAwayInSubfield.Read(M).At(T, carrier, g))),
				"T[1/g] is a subring",
				"it holds T",
				"it holds 1/g")
			rings := arg.Conjuncts(
				arg.Have(
					"S and T are rings under M's operations",
					"comm_ring_on(restrict_ring(field_ring(M), S)) ∧ comm_ring_on(restrict_ring(field_ring(M), T))",
					By(subS, subT, comm_ring.SubringRingOn.Read(ring).At(S), comm_ring.SubringRingOn.Read(ring).At(T))),
				"S is a ring",
				"T is a ring")
			ringPowers := arg.Have(
				"so dⁿ lies in S and eᵐ in T",
				"monoid_pow(M.mul, M.one, d, n) ∈ S ∧ monoid_pow(M.mul, M.one, e, m) ∈ T",
				By(
					dIn,
					eIn,
					comm_monoid.PowIn.Read(comm_ring.MulMonoidOn.Read(rings[0])).AsFact().At(d, n),
					comm_monoid.PowIn.Read(comm_ring.MulMonoidOn.Read(rings[1])).AsFact().At(e, m)))
			ig := field.InvIn.Read(M).At(gm)
			ih := field.InvIn.Read(M).At(hm)

			Sh := arg.TermAs[Set[A]]("ring_away(field_ring(M), S, h)")
			Tg := arg.TermAs[Set[A]]("ring_away(field_ring(M), T, g)")
			forward := arg.Have(
				"S[1/h] lies in T[1/g], which holds S and 1/h",
				"ring_away(field_ring(M), S, h) ⊆ ring_away(field_ring(M), T, g)",
				Derive(func(b *Argument) {
					eOne := b.Have(
						"y (1/g) e is one, as e y = g",
						"y * M.inv(g) * e = M.one",
						ByArith(M, Scaled(ig, gDef), gNonzero, em, ym, field.MulRightInverseOn.Read(M).At(gm), ig))
					inverseE := b.Have(
						"so 1/e = y/g",
						"M.inv(e) = y * M.inv(g)",
						By(eOne, field.InvLeftUniqueOn.Read(M).At(comm_ring.MulIn.Read(ring).At(ym, ig), em)))
					eInverted := b.Have(
						"so T[1/g] holds 1/e",
						"M.inv(e) ∈ ring_away(field_ring(M), T, g)",
						BySets(inverseE, raised, awayT[0], awayT[1], awayT[2], comm_ring.SubringDef.At(R, Tg)))
					throughE := b.Have(
						"and with it T[1/e]",
						"ring_away(field_ring(M), T, e) ⊆ ring_away(field_ring(M), T, g)",
						By(eInverted, awayT[0], awayT[1], eNonzero, RingAwayLeast.Read(M).At(T, Tg, em)))
					sIn := b.Have(
						"so T[1/g] holds S",
						"S ⊆ ring_away(field_ring(M), T, g)",
						BySets(sInAway, throughE))
					hOne := b.Have(
						"eᵐ (e/g) h is one, as eᵐ e h = e y = g",
						"monoid_pow(M.mul, M.one, e, m) * (e * M.inv(g)) * h = M.one",
						ByArith(
							M,
							Scaled(ig, gDef),
							Scaled(b.TermAs[A]("e * M.inv(g)"), yDef),
							gNonzero,
							em,
							hm,
							ym,
							field.MulRightInverseOn.Read(M).At(gm),
							ig))
					inverseH := b.Have(
						"so 1/h = eᵐ e/g",
						"M.inv(h) = monoid_pow(M.mul, M.one, e, m) * (e * M.inv(g))",
						By(
							hOne,
							field.InvLeftUniqueOn.Read(M).At(
								comm_ring.MulIn.Read(ring).At(powerE, comm_ring.MulIn.Read(ring).At(em, ig)), hm)))
					hInverted := b.Have(
						"so T[1/g] holds 1/h",
						"M.inv(h) ∈ ring_away(field_ring(M), T, g)",
						BySets(inverseH, ringPowers, eIn, awayT[0], awayT[1], awayT[2], comm_ring.SubringDef.At(R, Tg)))
					b.Show(
						"so it holds the least subring holding S and 1/h",
						By(hInverted, awayT[0], sIn, hNonzero, RingAwayLeast.Read(M).At(S, Tg, hm)))
				}))
			backward := arg.Have(
				"T[1/g] lies in S[1/h], which holds T and 1/g",
				"ring_away(field_ring(M), T, g) ⊆ ring_away(field_ring(M), S, h)",
				Derive(func(b *Argument) {
					dOne := b.Have(
						"x (1/h) d is one, as d x = h",
						"x * M.inv(h) * d = M.one",
						ByArith(M, Scaled(ih, hDef), hNonzero, dm, xm, field.MulRightInverseOn.Read(M).At(hm), ih))
					inverseD := b.Have(
						"so 1/d = x/h",
						"M.inv(d) = x * M.inv(h)",
						By(dOne, field.InvLeftUniqueOn.Read(M).At(comm_ring.MulIn.Read(ring).At(xm, ih), dm)))
					dInverted := b.Have(
						"so S[1/h] holds 1/d",
						"M.inv(d) ∈ ring_away(field_ring(M), S, h)",
						BySets(inverseD, cleared, awayS[0], awayS[1], awayS[2], comm_ring.SubringDef.At(R, Sh)))
					tIn := b.Have(
						"and with it S[1/d], which holds T",
						"T ⊆ ring_away(field_ring(M), S, h)",
						By(
							tInAway,
							dInverted,
							awayS[0],
							awayS[1],
							dNonzero,
							RingAwayLeast.Read(M).At(S, Sh, dm),
							set_order.SubsetTrans))
					eOne := b.Have(
						"dⁿ (d/h) e is one, as dⁿ d e = d x = h",
						"monoid_pow(M.mul, M.one, d, n) * (d * M.inv(h)) * e = M.one",
						ByArith(
							M,
							Scaled(ih, hDef),
							Scaled(b.TermAs[A]("d * M.inv(h)"), xDef),
							hNonzero,
							dm,
							em,
							xm,
							field.MulRightInverseOn.Read(M).At(hm),
							ih))
					inverseE := b.Have(
						"so 1/e = dⁿ d/h",
						"M.inv(e) = monoid_pow(M.mul, M.one, d, n) * (d * M.inv(h))",
						By(
							eOne,
							field.InvLeftUniqueOn.Read(M).At(
								comm_ring.MulIn.Read(ring).At(powerD, comm_ring.MulIn.Read(ring).At(dm, ih)), em)))
					eInverted := b.Have(
						"so S[1/h] holds 1/e",
						"M.inv(e) ∈ ring_away(field_ring(M), S, h)",
						BySets(inverseE, ringPowers, dIn, awayS[0], awayS[1], awayS[2], comm_ring.SubringDef.At(R, Sh)))
					throughE := b.Have(
						"and with it T[1/e]",
						"ring_away(field_ring(M), T, e) ⊆ ring_away(field_ring(M), S, h)",
						By(eInverted, awayS[0], tIn, eNonzero, RingAwayLeast.Read(M).At(T, Sh, em)))
					powerInverse := b.Have(
						"1/eᵐ lies in T[1/e], eᵐ carrying it to one",
						"M.inv(monoid_pow(M.mul, M.one, e, m)) ∈ ring_away(field_ring(M), T, e)",
						By(
							subT,
							nonzeroPowers.At(e, m),
							em,
							eNonzero,
							field.MulRightInverseOn.Read(M).At(powerE),
							field.InvIn.Read(M).At(powerE),
							comm_ring.SubringDef.At(R, T),
							RingAwayMember.At(R, T, e, b.TermAs[A]("M.inv(monoid_pow(M.mul, M.one, e, m))"))))
					powerInverseIn := b.Have(
						"so it lies in S[1/h]",
						"M.inv(monoid_pow(M.mul, M.one, e, m)) ∈ ring_away(field_ring(M), S, h)",
						BySets(powerInverse, throughE))
					inverseG := b.Have(
						"1/g = (1/e)(1/eᵐ)(1/h), as g = e eᵐ h",
						"M.inv(g) = M.inv(e) * (M.inv(monoid_pow(M.mul, M.one, e, m)) * M.inv(h))",
						By(gDef, yDef, field.InvMulOn.Read(M).At(em, ym), field.InvMulOn.Read(M).At(powerE, hm)))
					gInverted := b.Have(
						"so S[1/h] holds 1/g",
						"M.inv(g) ∈ ring_away(field_ring(M), S, h)",
						By(inverseG, eInverted, powerInverseIn, awayS[0], awayS[2], comm_ring.SubringDef.At(R, Sh)))
					b.Show(
						"so it holds the least subring holding T and 1/g",
						By(gInverted, awayS[0], tIn, gNonzero, RingAwayLeast.Read(M).At(T, Sh, gm)))
				}))
			arg.Take(h)
			arg.Take(g)
			arg.Show(
				"the two inclusions make the rings equal",
				By(hIn, hNonzero, gIn, gNonzero, forward, backward, set_order.SubsetAntisym))
		}),
})}

// AwayPrincipalIdealDomain — a principal ideal domain S inside a field stays one
// with a nonzero member d inverted. An ideal J of S[1/d] meets S in an ideal, the
// multiples of some c in S; a member r of J has dⁿ r in that contraction, so
// dⁿ r = c s, and r is the multiple of c by d⁻ⁿ s.
var AwayPrincipalIdealDomain = awayPrincipalIdealDomainThm{family.Add(registry.ProofEntry{
	Name: "AwayPrincipalIdealDomain",
	Key:  "prop_4d1c6de62da9b3fa",
	Build: family.Theorem(Statement{
		Binders: "∀L:field_on(A). ∀S:set(A). ∀d:A.",
		Hypotheses: []string{
			"subring(field_ring(L), S)",
			"principal_ideal_domain(restrict_ring(field_ring(L), S))",
			"d ∈ S",
			"d ≠ L.zero",
		},
		Conclusion: "principal_ideal_domain(restrict_ring(field_ring(L), «away»))",
		Abbrev: Abbrev{
			{Name: "away", Text: "ring_away(field_ring(L), S, d)"},
		},
	},
		func(
			arg *Argument,
			L field.FieldFact[on.L],
			S *Expr[Set[A]],
			d *Expr[A],
			subringS, principal, dInS, nonzero Fact,
		) {
			R := arg.TermAs[RingOps[A]]("field_ring(L)")
			ring := field.RingOn.Read(L)
			monoid := comm_ring.MulMonoidOn.Read(ring)
			sOpen := arg.Unfolded(subringS, comm_ring.SubringDef)
			sInL := comm_ring.SubringSubset.Read(subringS)
			dInL := arg.Have(
				"d lies in L",
				"d ∈ L.carrier",
				BySets(dInS, sInL))
			inverted := arg.Have(
				"its inverse lies in L and inverts d",
				"L.inv(d) ∈ L.carrier ∧ d * L.inv(d) = L.one",
				By(dInL, nonzero, field.InvIn.Read(L), field.MulRightInverseOn.Read(L)))
			awayFacts := arg.Conjuncts(
				arg.Have(
					"S[1/d] is a subring of L holding S and the inverse of d",
					"S ⊆ «away» ∧ subring(field_ring(L), «away») ∧ L.inv(d) ∈ «away»",
					By(ring, subringS, dInS, inverted, RingAwaySubring.At(R, S, d))),
				"S lies in S[1/d]",
				"S[1/d] is a subring of L",
				"it holds the inverse of d")
			sInAway, subringAway, inverseInAway := awayFacts[0], awayFacts[1], awayFacts[2]
			away := arg.TermAs[Set[A]]("«away»")
			awayOpen := arg.Unfolded(subringAway, comm_ring.SubringDef)
			awayInL := arg.Have(
				"S[1/d] lies in L",
				"«away» ⊆ L.carrier",
				By(comm_ring.SubringSubset.Read(subringAway)))
			awayRing := arg.Have(
				"so it is a ring on its set",
				"comm_ring_on(restrict_ring(field_ring(L), «away»))",
				By(subringAway, comm_ring.SubringRingOn.Read(ring).At(away)))
			awayMonoid := comm_ring.MulMonoidOn.Read(awayRing)
			domain := arg.Have(
				"a subring of the field L, it is an integral domain",
				"integral_domain_on(restrict_ring(field_ring(L), «away»))",
				By(subringAway, integral_domain.SubringOfFieldDomain.Read(L).At(away)))
			clauses := arg.Conjuncts(
				arg.Unfolded(principal, principal_ideal_domain.PrincipalIdealDomainDef),
				"S is an integral domain",
				"every ideal of S is the multiples of one of its members")
			everyIdeal := clauses[1]
			generated := arg.Have(
				"every ideal of S[1/d] is the multiples of one of its members",
				Statement{
					Binders: "∀J:set(A).",
					Hypotheses: []string{
						"ring_ideal(restrict_ring(field_ring(L), «away»), J)",
					},
					Conclusion: "∃c:A. c ∈ «away» ∧ J = image(L.mul(c), «away»)",
				},
				Derive(func(b *Argument) {
					b.FixAs[Set[A]]("J")
					ideal := b.Assume()
					parts := b.Conjuncts(
						b.Unfolded(ideal, ring_ideal.RingIdealDef),
						"J lies in S[1/d]",
						"J holds zero",
						"J is closed under the sum",
						"J absorbs the products by members of S[1/d]")
					absorbs := parts[3]
					contraction := b.TermAs[Set[A]]("S ∩ J")
					contracted := b.Have(
						"S ∩ J is an ideal of S",
						"ring_ideal(restrict_ring(field_ring(L), S), S ∩ J)",
						Simp(Fwd(ring_ideal.RingIdealDef)),
						BySets(parts[1], parts[2], absorbs, sOpen, sInAway))
					c, spanned := b.ObtainAs[A](
						"it is the multiples of some c in S",
						"∃c:A. c ∈ S ∧ S ∩ J = image(L.mul(c), S)",
						By(contracted, everyIdeal.At(contraction)))
					cData := b.Conjuncts(
						spanned,
						"c lies in S",
						"S ∩ J is its multiples in S")
					cInS, multiples := cData[0], cData[1]
					cInField := b.Have(
						"c lies in L",
						"c ∈ L.carrier",
						BySets(cInS, sInL))
					cInAway := b.Have(
						"and in S[1/d]",
						"c ∈ «away»",
						BySets(cInS, sInAway))
					own := b.Have(
						"c is its own multiple by one",
						"∃x:A. c = L.mul(c, x) ∧ x ∈ S",
						Witness(b.TermAs[A]("L.one")),
						ByArith(ring, cInField, sOpen))
					cInJ := b.Have(
						"so c lies in J",
						"c ∈ S ∩ J",
						BySets(own, multiples))
					b.Take(c)
					b.Do(SplitConj(
						Case(
							"c lies in S[1/d]",
							By(cInAway)),
						Case(
							"and J is its multiples there",
							Simp(Fwd(set_basic.Extension)),
							Derive(func(e *Argument) {
								r := e.FixAs[A]("x")
								e.Iff()
								e.Forward(
									"a power of d brings a member of J into S ∩ J, the multiples of c in S",
									func(f *Argument, inJ Fact) {
										rInAway := f.Have(
											"r lies in S[1/d]",
											"x ∈ «away»",
											BySets(inJ, parts[0]))
										n, cleared := f.UnpackAs[Nat](
											f.Have(
												"so a power of d brings it into S",
												"∃n:num. monoid_pow(L.mul, L.one, d, n) * x ∈ S",
												By(rInAway, RingAwayMember.At(R, S, d, r))),
											"n")
										denominator := f.TermAs[A]("monoid_pow(L.mul, L.one, d, n)")
										reciprocal := f.TermAs[A]("monoid_pow(L.mul, L.one, L.inv(d), n)")
										inverseD := f.TermAs[A]("L.inv(d)")
										dInAway := f.Have(
											"d lies in S[1/d]",
											"d ∈ «away»",
											BySets(dInS, sInAway))
										inAwayPowers := f.Have(
											"so do the powers of d and of its inverse",
											"monoid_pow(L.mul, L.one, d, n) ∈ «away» ∧ monoid_pow(L.mul, L.one, L.inv(d), n) ∈ «away»",
											By(
												dInAway,
												inverseInAway,
												comm_monoid.PowIn.Read(awayMonoid).AsFact().At(d, n),
												comm_monoid.PowIn.Read(awayMonoid).AsFact().At(inverseD, n)))
										inFieldPowers := f.Have(
											"these powers lie in L",
											"monoid_pow(L.mul, L.one, d, n) ∈ L.carrier ∧ monoid_pow(L.mul, L.one, L.inv(d), n) ∈ L.carrier",
											By(
												dInL,
												inverted,
												comm_monoid.PowIn.Read(monoid).AsFact().At(d, n),
												comm_monoid.PowIn.Read(monoid).AsFact().At(inverseD, n)))
										inverseProduct := f.Have(
											"and invert each other",
											"monoid_pow(L.mul, L.one, d, n) * monoid_pow(L.mul, L.one, L.inv(d), n) = L.one",
											By(dInL, inverted, comm_monoid.PowInverseOn.Read(monoid).AsFact().At(d, inverseD, n)))
										inContraction := f.Have(
											"the cleared member lies in S ∩ J",
											"monoid_pow(L.mul, L.one, d, n) * x ∈ S ∩ J",
											BySets(cleared, inAwayPowers, inJ, absorbs.At(denominator, r)))
										_, factored := f.ObtainAs[A](
											"so it is c times a member of S",
											"∃s:A. monoid_pow(L.mul, L.one, d, n) * x = L.mul(c, s) ∧ s ∈ S",
											BySets(inContraction, multiples))
										factors := f.Conjuncts(
											factored,
											"the cleared member is c s",
											"s lies in S")
										sOfAway := f.Have(
											"s lies in S[1/d] and in L",
											"s ∈ «away» ∧ s ∈ L.carrier",
											BySets(factors[1], sInAway, sInL))
										quotientIn := f.Have(
											"so d⁻ⁿ s lies in S[1/d]",
											"monoid_pow(L.mul, L.one, L.inv(d), n) * s ∈ «away»",
											By(sOfAway, inAwayPowers, awayOpen))
										rInField := f.Have(
											"r lies in L",
											"x ∈ L.carrier",
											BySets(rInAway, awayInL))
										equation := f.Have(
											"r is c times d⁻ⁿ s",
											"x = L.mul(c, monoid_pow(L.mul, L.one, L.inv(d), n) * s)",
											ByArith(
												ring,
												inFieldPowers,
												rInField,
												cInField,
												sOfAway,
												Scaled(r, inverseProduct),
												Scaled(reciprocal, factors[0])))
										witnessed := f.Have(
											"which is a multiple of c in S[1/d]",
											"∃y:A. x = L.mul(c, y) ∧ y ∈ «away»",
											Witness(f.TermAs[A]("monoid_pow(L.mul, L.one, L.inv(d), n) * s")),
											By(equation, quotientIn))
										f.Show(
											"as claimed",
											By(witnessed, set_basic.InImage.At(f.TermAs[Fun[A, A]]("L.mul(c)"), away, r)))
									})
								e.Backward(
									"a multiple of c lies in J",
									func(f *Argument, inImage Fact) {
										y, multiple := f.UnpackAs[A](
											f.Have(
												"it is c times a member y of S[1/d]",
												"∃y:A. x = L.mul(c, y) ∧ y ∈ «away»",
												By(inImage, set_basic.InImage.At(f.TermAs[Fun[A, A]]("L.mul(c)"), away, r))),
											"y")
										data := f.Conjuncts(
											multiple,
											"x is c y",
											"y lies in S[1/d]")
										yInField := f.Have(
											"y lies in L",
											"y ∈ L.carrier",
											BySets(data[1], awayInL))
										swapped := f.Have(
											"so c y is y c",
											"L.mul(c, y) = y * c",
											ByArith(ring, cInField, yInField))
										cMember := f.Have(
											"c lies in J",
											"c ∈ J",
											BySets(cInJ))
										f.Show(
											"and J absorbs the product",
											data[0].Rw(),
											swapped.Rw(),
											By(data[1], cMember, absorbs.At(y, c)))
									})
							}))))
				}))
			arg.Show(
				"so S[1/d] is a principal ideal domain",
				By(domain, generated, principal_ideal_domain.PrincipalIdealDomainDef))
		}),
})}

// AwayCoverMember — a member z of L that each S[1/g] holds, for the g of a
// set X generating the unit ideal of S, lies in S: the w of S with w·z in S
// are an ideal of S holding a power of every g; were z outside S that ideal
// would miss one and lie in a maximal ideal, prime, so holding every g, and
// with them the unit ideal they generate.
var AwayCoverMember = awayCoverMemberThm{family.Add(registry.ProofEntry{
	Name: "AwayCoverMember",
	Key:  "prop_9b06cfc14aa4d592",
	Reading: "Only the unit ideal's being generated by X is read, no finiteness of " +
		"X: one is a finite combination of members of X in any case. z ∈ L.carrier is " +
		"what makes the multipliers of z an ideal, the product distributing over L's sum.",
	Build: family.Theorem(Statement{
		Binders: "∀L:field_on(A). ∀S X:set(A). ∀z:A.",
		Hypotheses: []string{
			"subring(field_ring(L), S)",
			"X ⊆ S",
			"L.one ∈ ideal_span(restrict_ring(field_ring(L), S), X)",
			"z ∈ L.carrier",
			"∀g:A. g ∈ X ⇒ ∃n:num. monoid_pow(L.mul, L.one, g, n) * z ∈ S",
		},
		Conclusion: "z ∈ S",
		Abbrev: Abbrev{
			{Name: "multipliers", Text: "{w:A | w ∈ S ∧ w * z ∈ S}"},
		},
	},
		func(
			a *Argument,
			L field.FieldFact[on.L],
			S, X *Expr[Set[A]],
			z *Expr[A],
			subring, generators, unit, zIn, powers Fact,
		) {
			ring := field.RingOn.Read(L)
			ops := a.TermAs[RingOps[A]]("restrict_ring(field_ring(L), S)")
			ringS := a.Have(
				"S is a ring under the operations of L",
				"comm_ring_on(restrict_ring(field_ring(L), S))",
				By(subring, comm_ring.SubringRingOn.Read(ring).At(S)))
			sInL := a.Have(
				"S lies in L",
				"S ⊆ L.carrier",
				By(comm_ring.SubringSubset.Read(subring)))
			zm := a.MemberOf[on.L](z, zIn)
			ideal := a.Have(
				"the multipliers of z in S are an ideal of S: products and sums of multipliers multiply z into S",
				"ring_ideal(restrict_ring(field_ring(L), S), «multipliers»)",
				Simp(Fwd(ring_ideal.RingIdealDef)),
				Derive(func(b *Argument) {
					zero := b.Have(
						"zero multiplies z to zero, in S",
						"L.zero * z = L.zero",
						ByArith(L, zm))
					sums := b.Have(
						"(v + w)·z = v·z + w·z",
						"∀v w:A. v ∈ S ∧ w ∈ S ⇒ (v + w) * z = v * z + w * z",
						Derive(func(c *Argument) {
							c.FixAs[A]("v")
							c.FixAs[A]("w")
							inL := c.Have(
								"both lie in L",
								"v ∈ L.carrier ∧ w ∈ L.carrier",
								BySets(c.Assume(), sInL))
							c.Show(
								"the product distributes over the sum",
								ByArith(L, zm, inL))
						}))
					multiples := b.Have(
						"(u·w)·z = u·(w·z)",
						"∀u w:A. u ∈ S ∧ w ∈ S ⇒ u * w * z = u * (w * z)",
						Derive(func(c *Argument) {
							c.FixAs[A]("u")
							c.FixAs[A]("w")
							inL := c.Have(
								"both lie in L",
								"u ∈ L.carrier ∧ w ∈ L.carrier",
								BySets(c.Assume(), sInL))
							c.Show(
								"the product is associative",
								ByArith(L, zm, inL))
						}))
					b.Show(
						"so the multipliers hold zero and are closed under sums and multiples from S",
						BySets(
							zero,
							sums,
							multiples,
							comm_ring.SubringZero.Read(subring),
							comm_ring.SubringAdd.Read(subring),
							comm_ring.SubringMul.Read(subring)))
				}))
			inside := a.Have(
				"a power of every g of X is a multiplier of z",
				"∀g:A. g ∈ X ⇒ ∃n:num. monoid_pow(L.mul, L.one, g, n) ∈ «multipliers»",
				BySets(powers, generators, comm_monoid.PowIn.Read(comm_ring.MulMonoidOn.Read(ringS))))
			a.Show(
				"else the multipliers lie in a maximal ideal, prime, holding X and so one",
				Derive(func(b *Argument) {
					outside := b.SupposeNot()
					unitTimes := b.Have(
						"one times z is z",
						"L.one * z = z",
						ByArith(L, zm))
					missesOne := b.Have(
						"so one is no multiplier of z, z lying outside S",
						"L.one ∉ «multipliers»",
						BySets(outside, unitTimes))
					m, maximal := b.ObtainAs[Set[A]](
						"so the multipliers lie in a maximal ideal m of S",
						"∃m:set(A). maximal_ideal(restrict_ring(field_ring(L), S), m) ∧ «multipliers» ⊆ m",
						By(
							ideal,
							missesOne,
							ringS,
							ring_ideal.ExistsMaximalAbove.Read(ringS).At(b.TermAs[Set[A]]("«multipliers»"))),
						Named("m"))
					parts := b.Conjuncts(
						maximal,
						"m is maximal",
						"and holds the multipliers")
					prime := b.Have(
						"m is prime",
						"prime_ideal(restrict_ring(field_ring(L), S), m)",
						By(parts[0], ring_ideal.MaximalIsPrime.Read(ringS)))
					holdsEach := b.Have(
						"m holds a power of every g of X, so, prime, every g",
						"∀g:A. g ∈ X ⇒ g ∈ m",
						Derive(func(c *Argument) {
							g := c.FixAs[A]("g")
							gIn := c.Assume()
							n, power := c.UnpackAs[Nat](GroupPremises(gIn, inside.At(g)), "n")
							c.Show(
								"a prime holding a power of g holds g",
								By(
									power,
									parts[1],
									prime,
									gIn,
									generators,
									set_basic.SubsetDef,
									ring_ideal.PrimeIdealPow.Read(ringS).AsFact().At(m, g, n)))
						}))
					holdsX := b.Have(
						"so m holds X",
						"X ⊆ m",
						BySets(holdsEach))
					b.Show(
						"so m holds the unit ideal X generates, and one, which a maximal ideal does not",
						By(
							unit,
							holdsX,
							parts[0],
							ring_ideal.MaximalIdealIdeal.At(ops, m),
							ring_ideal.SpanLeast.At(ops, X, m),
							ring_ideal.MaximalIdealProper.At(ops, m),
							set_basic.SubsetDef))
				}))
		}),
})}
